,p_computation_point=>'AFTER_LOGIN'
,p_computation_type=>'QUERY'
,p_computation_processed=>'REPLACE_EXISTING'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DECODE(NVL(USER_LANGUAGE_ID, 1), 1, ''ar'', ''en'' )',
'  FROM APP_USERS',
' WHERE ID = :P_USER_ID'))
,p_version_scn=>1
);
