begin
wwv_flow_imp_shared.create_automation(
 p_id=>wwv_flow_imp.id(222268397692625696)
,p_name=>'Increase Salary'
,p_static_id=>'increase-salary'
,p_trigger_type=>'POLLING'
,p_polling_interval=>'FREQ=MINUTELY;INTERVAL=5'
,p_polling_status=>'DISABLED'
,p_result_type=>'ROWS'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_query_type=>'TABLE'
,p_query_table=>'EMP'
,p_include_rowid_column=>false
,p_pk_column_name=>'EMPNO'
,p_commit_each_row=>false
,p_error_handling_type=>'IGNORE'
);
wwv_flow_imp_shared.create_automation_action(
 p_id=>wwv_flow_imp.id(222268667952625698)
,p_automation_id=>wwv_flow_imp.id(222268397692625696)
,p_name=>'Update Developers Salary'
,p_execution_sequence=>10
,p_action_type=>'NATIVE_PLSQL'
,p_action_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    UPDATE EMP SET SAL = SAL + 1500 WHERE UPPER(JOB) = UPPER(''Developer'') AND EMPNO = :EMPNO;',
'    APEX_AUTOMATION.log_info(''Salary for '' || :ENAME || '' increased.'');',
'END;'))
,p_action_clob_language=>'PLSQL'
,p_attribute_10=>'N'
,p_attribute_14=>'HTML'
,p_location=>'LOCAL'
,p_error_message=>'Salary not increased.'
,p_stop_execution_on_error=>true
,p_condition_type=>'EXPRESSION'
,p_condition_expr1=>'UPPER(:JOB) = UPPER(''Developer'')'
,p_condition_expr2=>'PLSQL'
,p_exec_cond_for_each_row=>true
);
end;
