prompt --application/shared_components/plugins/item_type/com_ilaurensse_tagsitem
begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(247245531548391542)
,p_plugin_type=>'ITEM TYPE'
,p_name=>'COM.ILAURENSSE.TAGSITEM'
,p_display_name=>'Tags Item'
,p_supported_component_types=>'APEX_APPLICATION_PAGE_ITEMS'
,p_image_prefix => nvl(wwv_flow_application_install.get_static_plugin_file_prefix('ITEM TYPE','COM.ILAURENSSE.TAGSITEM'),'')
,p_javascript_file_urls=>'#PLUGIN_FILES#inputTags.jquery.min.js'
,p_css_file_urls=>'#PLUGIN_FILES#inputTags.min.css'
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'PROCEDURE render_tags_item (',
'    p_item     IN apex_plugin.t_page_item,',
'    p_plugin   IN apex_plugin.t_plugin,',
'    p_param    IN apex_plugin.t_item_render_param,',
'    p_result   IN OUT NOCOPY apex_plugin.t_item_render_result',
')',
' IS',
'  l_read_only           p_param.is_readonly%type          := p_param.is_readonly;',
'  l_is_printer_friendly p_param.is_printer_friendly%type  := p_param.is_printer_friendly;',
'  l_item_max_length     p_item.element_max_length%type    := p_item.element_max_length;',
'  l_item_size           p_item.element_width%type         := p_item.element_width;',
'  l_item_name           varchar2(1000)                    := p_item.name;',
'  l_js_code             varchar2(4000);',
'  l_max_tags            p_item.attribute_01%type          := p_item.attribute_01;',
'  l_target_url          p_item.attribute_02%type          := p_item.attribute_02;',
'  l_tags_lov            p_item.attribute_03%type          := p_item.attribute_03;',
'  l_other_values        p_item.attribute_04%type          := p_item.attribute_04;',
'  l_editable            varchar2(5);',
'  l_restricted          varchar2(5);',
'  l_report_url          varchar2(4000);',
'  l_page_mode           varchar2(200);',
'',
'  l_column_value_list   apex_plugin_util.t_column_value_list;',
'begin',
' ',
'  if apex_application.g_debug ',
'  then',
'    apex_plugin_util.debug_page_item ( p_plugin                => p_plugin,',
'                                       p_page_item             => p_item,',
'                                       p_value                 => p_param.value,',
'                                       p_is_readonly           => l_read_only,',
'                                       p_is_printer_friendly   => l_is_printer_friendly);',
'  end if;',
'',
'  -- Is the current page a Modal Dialog or Normal page? ',
'  -- Needed for a proper redirect to a different page.',
'  select case',
'           when page_mode like ''Modal%'' then ''modal''',
'           else ''normal''',
'         end  ',
'  into l_page_mode',
'  from  apex_application_pages',
'  where application_id = :app_id',
'  and page_id = :app_page_id;',
'',
'  if l_read_only',
'  then',
'    l_editable := ''false'';',
'  else ',
'    l_editable := ''true'';',
'  end if;',
'',
'  if l_other_values = ''N''',
'   then',
'    l_restricted := ''true'';',
'  else',
'    l_restricted := ''false'';',
'  end if;',
'   ',
'  if l_tags_lov is not null',
'  then',
'    l_column_value_list :=',
'        apex_plugin_util.get_data (',
'            p_sql_statement    => l_tags_lov',
'           ,p_min_columns      => 1 --2',
'           ,p_max_columns      => 1 --2',
'           ,p_component_name   => p_item.name',
'            );',
'',
'    --Example of a tags LOV list:',
'    --l_tags_lov := ''[''''BAG'''', ''''WOMEN'''', ''''MEN'''', ''''ACCESSORY'''']'';',
'    if l_column_value_list(1).count > 0',
'    then',
'      l_tags_lov := ''['';',
'      for i in 1 .. l_column_value_list(1).count',
'      loop',
'        l_tags_lov := l_tags_lov || '''''''' || sys.htf.escape_sc(l_column_value_list(1)(i))|| '''''',''; -- return column',
'      end loop;',
'      l_tags_lov := rtrim(l_tags_lov) || '']'';',
'    end if;',
'  end if;',
'',
'  sys.htp.prn(''<input type="text" id="''||l_item_name||''" name="''||l_item_name||''"" value="''||p_param.value||''">'');',
'',
'  l_js_code := ''$("#''||l_item_name||''").inputTags({ editable:'' || l_editable ||'',''',
'                                                 ||''destroy:'' || l_editable || '',''',
'                                                 ||''create:'' || l_editable ||'',''',
'                                                 ||''url:''''''|| l_target_url ||'''''',''',
'                                                 ||''max:''''''|| l_max_tags ||'''''',''',
'                                                 ||''pagemode:''''''|| l_page_mode ||''''''''',
'                                                 ||case',
'                                                      when l_tags_lov is not null then '',autocomplete: {values: ''||l_tags_lov||'', ''||''only: ''||l_restricted ||''}''',
'                                                      else null',
'                                                   end',
'                                                 ||'' });'';                                                    ',
'  apex_javascript.add_onload_code (l_js_code);',
'    ',
' End render_tags_item;'))
,p_api_version=>2
,p_render_function=>'render_tags_item'
,p_standard_attributes=>'VISIBLE:READONLY:SOURCE:ELEMENT:WIDTH'
,p_substitute_attributes=>true
,p_version_scn=>1
,p_subscribe_plugin_settings=>true
,p_version_identifier=>'1.0'
,p_files_version=>74
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(247810481724412752)
,p_plugin_id=>wwv_flow_imp.id(247245531548391542)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>10
,p_static_id=>'attribute_01'
,p_prompt=>'Maximum number of tags'
,p_attribute_type=>'NUMBER'
,p_is_required=>true
,p_default_value=>'15'
,p_is_translatable=>false
,p_help_text=>'Enter the maximum number of tags that can be entered.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(247810970967429127)
,p_plugin_id=>wwv_flow_imp.id(247245531548391542)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>2
,p_display_sequence=>20
,p_static_id=>'attribute_02'
,p_prompt=>'Tag link'
,p_attribute_type=>'LINK'
,p_is_required=>false
,p_is_translatable=>false
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Link Item Name P1_TAG, Value !TAG!<br>',
'Sample report query for a tag:',
'<pre>',
'select p.product_id,',
'       p.product_name, ',
'       p.product_description, ',
'       tags',
'from demo_product_info p',
'where (:P1_TAG is null',
'   or instr('',''||tags||'','' , '',''||:P1_TAG||'','') > 0',
')',
'</pre>'))
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Optional link to another page when clicking on a tag. For example, a report page to show all records with that tag.<br>',
'Use !TAG! to pass the value of tag.'))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(251054184069917472)
,p_plugin_id=>wwv_flow_imp.id(247245531548391542)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>3
,p_display_sequence=>30
,p_static_id=>'attribute_03'
,p_prompt=>'Tags LOV query'
,p_attribute_type=>'SQL'
,p_is_required=>false
,p_sql_min_column_count=>1
,p_sql_max_column_count=>1
,p_is_translatable=>false
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<pre>',
'select tag',
'from mytags',
'where tag_type = ''PRODUCT''',
'</pre>'))
,p_help_text=>'A query that returns valid tags.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(251054990976951690)
,p_plugin_id=>wwv_flow_imp.id(247245531548391542)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>4
,p_display_sequence=>40
,p_static_id=>'attribute_04'
,p_prompt=>'Allow other values'
,p_attribute_type=>'CHECKBOX'
,p_is_required=>false
,p_default_value=>'Y'
,p_is_translatable=>false
,p_help_text=>'Restrict tags to the values in the LOV or not.'
);
end;
