,p_javascript_file_urls=>'https://unpkg.com/@lottiefiles/lottie-player@latest/dist/lottie-player.js'
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'.a-IRR-noDataMsg-icon {',
'    display: none;',
'}',
'',
'lottie-player {',
'    margin: 0 auto;',
'}'))
,p_page_template_options=>'#DEFAULT#'
,p_required_role=>'MUST_NOT_BE_PUBLIC_USER'
,p_protection_level=>'C'
,p_page_component_map=>'18'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(212229749147033326)
,p_plug_name=>'Requests Container'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(217785771929592374)
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT m.ID,',
'       m.SELLER_ID,',
'       m.USER_ID,',
'       m.CITY_ID,',
'       m.SEQUENCE,',
'       m.NAME,',
'       m.STATUS_ID,',
'       NVL((SELECT f.FILE_URL FROM SELLER_ASSIGNED_FILES f WHERE f.ID = m.FILE_ID), ''#'') AS FILE_URL,',
'       m.IS_ACTIVE,',
'       m.CREATED_BY,',
'       m.CREATED_DATE,',
'       m.MODIFIED_BY,',
'       m.MODIFIED_DATE,',
'       m.FILE_ID,',
'       (SELECT count(1) FROM seller_assigned_files_details WHERE master_id = m.id and is_active = 1 ) AS VEHICLES_COUNT,',
'       ''<span aria-hidden="true" class="t-Icon fa fa-cloud-upload"></span>'' AS UPLOAD,',
'       ',
'       ''<span aria-hidden="true" class="t-Icon fa fa-cloud-upload"></span>'' AS UPLOAD_PAYMENT_DOCUMENT,',
'       m.AGENT_INSPECTION_PAYMENT_DOCUMENT,',
'       CASE',
'      WHEN m.AGENT_INSPECTION_PAYMENT_DOCUMENT IS NOT NULL THEN',
'          ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'      ELSE ''''',
'      END AS AGENT_INSPECTION_PAYMENT_DOCUMENT_CLASS,',
'       m.INSPECTION_PAYMENT_DOCUMENT,',
'       CASE',
'      WHEN m.INSPECTION_PAYMENT_DOCUMENT IS NOT NULL THEN',
'          ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'      ELSE ''''',
'      END AS INSPECTION_PAYMENT_DOCUMENT_CLASS',
'  FROM SELLER_ASSIGNED_FILES_MASTER m',
' WHERE (CHECKER_USER_ID = :P_USER_ID OR :P_USER_ID IN (10000, 10002, 9915, 9897, 10610,10621))',
'   AND IS_ACTIVE = 1',
