'            LEFT_REAR_FENDER, RIGHT_FRONT_DOOR, LEFT_FRONT_DOOR, RIGHT_REAR_DOOR, LEFT_REAR_DOOR, THE_HOOD, THE_ROOF, THE_TRUNK, THE_ENTIRE_CAR',
'        ) VALUES (',
'            :P4_ID, :P4_IS_CAR_WORKING, :P4_IS_CAR_HAVE_KEY, :P4_TRANSMISSION_TYPE, :P4_OODO_METER, :P4_MISSING_PIECES, :P4_NOTES, :P4_RIGHT_FRONT_FENDER, :P4_LEFT_FRONT_FENDER, :P4_RIGHT_REAR_FENDER,',
'            :P4_LEFT_REAR_FENDER, :P4_RIGHT_FRONT_DOOR, :P4_LEFT_FRONT_DOOR, :P4_RIGHT_REAR_DOOR, :P4_LEFT_REAR_DOOR, :P4_THE_HOOD, :P4_THE_ROOF, :P4_THE_TRUNK, :P4_THE_ENTIRE_CAR',
