wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(71188513420982615)
,p_process_sequence=>90
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Save inspection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_inspection_id      NUMBER;',
'    v_count              NUMBER;',
'    l_file_name          VARCHAR2(255);',
'    l_request_url	     VARCHAR2(32767);',
'    l_images_urls	     VARCHAR2(32767);',
'    l_prev_images_urls	 VARCHAR2(32767);',
'    v_item_value         VARCHAR2(32767);',
'    v_item_name_comment  VARCHAR2(32767);',
'    v_item_value_comment VARCHAR2(32767);',
'    v_rows_count_inspection_images NUMBER;',
'    v_rows_count_inspection_images_table NUMBER;',
'BEGIN',
'    IF :P4_IS_CHECKED = 1 THEN',
'        IF :P4_IS_EDITABLE = 1 THEN',
'            UPDATE INSPECTION',
'               SET IS_CAR_WORKING       = :P4_IS_CAR_WORKING ,',
'                   IS_CAR_HAVE_KEY      = :P4_IS_CAR_HAVE_KEY ,',
'                   TRANSMISSION_TYPE    = :P4_TRANSMISSION_TYPE ,',
'                   OODO_METER           = :P4_OODO_METER,',
'                   CAR_NAME             = :P4_CAR_NAME,',
'                   PLATE_NUMBER         = :P4_PLATE_NUMBER_FROM_INSPECTOR,',
'                --    MISSING_PIECES     = :P4_MISSING_PIECES,',
'                   NOTES                = :P4_NOTES,',
'                   RIGHT_FRONT_FENDER   = :P4_RIGHT_FRONT_FENDER ,',
'                   LEFT_FRONT_FENDER    = :P4_LEFT_FRONT_FENDER ,',
'                   RIGHT_REAR_FENDER    = :P4_RIGHT_REAR_FENDER ,',
'                   LEFT_REAR_FENDER     = :P4_LEFT_REAR_FENDER ,',
'                   RIGHT_FRONT_DOOR     = :P4_RIGHT_FRONT_DOOR ,',
'                   LEFT_FRONT_DOOR      = :P4_LEFT_FRONT_DOOR ,',
'                   RIGHT_REAR_DOOR      = :P4_RIGHT_REAR_DOOR ,',
'                   LEFT_REAR_DOOR       = :P4_LEFT_REAR_DOOR ,',
'                   THE_HOOD             = :P4_THE_HOOD ,',
'                   THE_ROOF             = :P4_THE_ROOF ,',
'                   THE_TRUNK            = :P4_THE_TRUNK ,',
'                --    THE_ENTIRE_CAR     = :P4_THE_ENTIRE_CAR,',
'                   ENGINE_NOISE         = :P4_ENGINE_NOISE,',
'                   VALVE_LIFTERS_NOISE  = :P4_VALVE_LIFTERS_NOISE,',
'                   ENGINE_SMOKE         = :P4_ENGINE_SMOKE,',
'                   ENGINE_DETACHED      = :P4_ENGINE_DETACHED,',
'                   AIRBAGS              = :P4_AIRBAGS,',
'                   VEHICLE_GLASS        = :P4_VEHICLE_GLASS,',
'                   FRONT_CHASSIS        = :P4_FRONT_CHASSIS,',
'                   REAR_CHASSIS         = :P4_REAR_CHASSIS,',
'                   FRONT_BUMPER_SUPPORT = :P4_FRONT_BUMPER_SUPPORT,',
'                   REAR_BUMPER_SUPPORT  = :P4_REAR_BUMPER_SUPPORT,',
'                   RADIATOR_MOUNT       = :P4_RADIATOR_MOUNT,',
'                   HAIL_DAMAGE          = :P4_HAIL_DAMAGE,',
'                   PAINT_THICKNESS      = :P4_PAINT_THICKNESS,',
'                   SCRATCHES            = :P4_SCRATCHES,',
'                   FOUR_WHEEL_DRIVE     = :P4_FOUR_WHEEL_DRIVE,',
'                   SEAT_MATERIAL        = :P4_SEAT_MATERIAL',
'                --    IS_EDITABLE          = 0',
'             WHERE ID = :P4_INSPECTION_ID;',
'             ',
'            IF SQL%ROWCOUNT = 0 THEN',
'                RAISE_APPLICATION_ERROR (-20005, ''Update Error!'');',
'            END IF;',
'',
'            -- INSPECTION IMAGES ',
'            FOR i IN (SELECT ITEM_NAME, REPLACE(ITEM_NAME, ''P''|| PAGE_ID || ''_'') AS TYPE FROM APEX_APPLICATION_PAGE_ITEMS WHERE APPLICATION_ID = :APP_ID AND PAGE_ID = :APP_PAGE_ID AND DISPLAY_AS NOT IN (''Hidden'', ''Display Only'')  AND ITEM_NAME NOT LI'
||'KE ''%_COMMENT%'') LOOP',
'                ',
'                SELECT COUNT(1)',
'                  INTO v_rows_count_inspection_images',
'                  FROM APEX_COLLECTIONS ',
'                 WHERE COLLECTION_NAME = ''INSPECTION_IMAGES''',
'                   AND c003 = i.TYPE',
'                   AND c004 = :P4_ID;',
'',
'                SELECT COUNT(1)',
'                  INTO v_rows_count_inspection_images_table',
'                  FROM APEX_COLLECTIONS ',
'                 WHERE COLLECTION_NAME = ''INSPECTION_IMAGES_FROM_TABLE''',
'                   AND c001 = i.TYPE',
'                   AND c003 = :P4_ID;',
'',
'                IF v_rows_count_inspection_images_table > 0 THEN',
'                    SELECT LISTAGG(c002, '','')',
'                      INTO l_prev_images_urls',
'                      FROM APEX_COLLECTIONS ',
'                     WHERE COLLECTION_NAME = ''INSPECTION_IMAGES_FROM_TABLE'' ',
'                       AND c001 = i.TYPE ',
'                       AND c003 = :P4_ID;',
'',
'                    l_images_urls :=  l_prev_images_urls || '','';',
'                END IF;',
'',
'                IF v_rows_count_inspection_images > 0  THEN',
'                    FOR j IN (SELECT c001 AS FILE_NAME, c002 AS MIME_TYPE, c003 AS TYPE, c004 AS CAR_DETAILS_ID, blob001 AS BLOB_CONTENT FROM apex_collections WHERE collection_name = ''INSPECTION_IMAGES'' AND c003 = i.TYPE AND c004 = :P4_ID) LOOP',
'                        l_file_name := TO_CHAR(get_current_date, ''YY'') ',
'                                            || DBMS_RANDOM.STRING(''x'', 8)',
'                                            || SYSTEM_CONTROLS.file_extension_by_mimetype(p_mimetype => j.MIME_TYPE);',
'',
'                        l_request_url := :LOCATION_URI || l_file_name;',
'',
'                        DBMS_CLOUD.put_object (',
'                            credential_name => :CREDENTIAL_NAME,',
'                            object_uri      => l_request_url,',
'                            contents        => j.blob_content',
'                        );',
'',
'                        l_images_urls := l_images_urls || l_request_url || '','';',
'                    END LOOP;',
'                END IF;',
'                ',
'                l_images_urls := SUBSTR(l_images_urls, 1, LENGTH(l_images_urls) - 1);',
'',
'                -- COMMENT ',
'                v_item_value := V(i.ITEM_NAME);',
'                v_item_name_comment := i.ITEM_NAME || ''_COMMENT'';',
'                v_item_value_comment := V(v_item_name_comment);',
'',
'',
'                -- ## DEBUGING ##',
'                apex_debug.message(''## BEFORE ## Item: %s'', i.item_name);',
'                apex_debug.message(''## BEFORE ## Images: %s'', l_images_urls);',
'                apex_debug.message(''## BEFORE ## Comment: %s Value: %s'', v_item_name_comment, v_item_value_comment);',
'',
'                SELECT COUNT(1)',
'                  INTO v_count',
'                  FROM INSPECTION_DETAILS ',
'                 WHERE INSPECTION_ID = :P4_INSPECTION_ID',
'                   AND ITEM_NAME = i.TYPE;',
'',
'                IF l_images_urls IS NOT NULL',
'                   OR (',
'                       INSTR('','' || :P4_ACCEPTABLE_STATUS_IDS || '','', '','' || v_item_value || '','') = 0',
'                       AND v_item_value_comment IS NOT NULL',
'                   )',
'                   OR (',
'                       INSTR('','' || :P4_ACCEPTABLE_STATUS_IDS || '','', '','' || v_item_value || '','') <> 0',
'                       AND v_count > 0',
'                   )',
'                THEN',
'                    -- SELECT COUNT(1)',
'                    --   INTO v_count',
'                    --   FROM INSPECTION_DETAILS ',
'                    --  WHERE INSPECTION_ID = :P4_INSPECTION_ID',
'                    --    AND ITEM_NAME = i.TYPE;',
'',
'                    IF v_count > 0 THEN',
'                        UPDATE INSPECTION_DETAILS',
'                           SET COMMENT_ = v_item_value_comment,',
'                               IMAGES_URL = l_images_urls',
'                         WHERE INSPECTION_ID = :P4_INSPECTION_ID',
'                           AND ITEM_NAME = i.TYPE;  ',
'',
'                        IF SQL%ROWCOUNT = 0 THEN',
'                            RAISE_APPLICATION_ERROR (-20007, ''Updating Error!'');',
'                        END IF;',
'                    ELSE',
'                        INSERT INTO INSPECTION_DETAILS (INSPECTION_ID, ITEM_NAME, COMMENT_, IMAGES_URL)',
'                                            VALUES (:P4_INSPECTION_ID, i.TYPE, v_item_value_comment, l_images_urls);',
'',
'                        IF SQL%ROWCOUNT = 0 THEN',
'                            RAISE_APPLICATION_ERROR (-20008, ''Insertion Error!'');',
'                        END IF;',
'                    END IF;',
'                END IF;',
'                ',
'                l_images_urls := NULL;',
'                v_item_value_comment := NULL;',
'',
'                -- ## After',
'                apex_debug.message(''## AFTER ## Item: %s'', i.item_name);',
'                apex_debug.message(''## AFTER ## Images: %s'', l_images_urls);',
'                apex_debug.message(''## AFTER ## Comment: %s Value: %s'', v_item_name_comment, v_item_value_comment);',
'            END LOOP; ',
'            ',
'            IF APEX_COLLECTION.collection_exists(''INSPECTION_IMAGES'') THEN',
'                APEX_COLLECTION.TRUNCATE_COLLECTION (p_collection_name => ''INSPECTION_IMAGES'');',
'            END IF;',
'            ',
'            IF APEX_COLLECTION.collection_exists(''INSPECTION_IMAGES_FROM_TABLE'') THEN',
'                APEX_COLLECTION.TRUNCATE_COLLECTION (p_collection_name => ''INSPECTION_IMAGES_FROM_TABLE'');',
'            END IF;',
'',
'        END IF; -- P4_IS_EDITABLE = 1',
'    ELSE',
'        INSERT INTO INSPECTION (',
'            CAR_DETAILS_ID, IS_CAR_WORKING, IS_CAR_HAVE_KEY, TRANSMISSION_TYPE, OODO_METER, CAR_NAME, PLATE_NUMBER, NOTES, RIGHT_FRONT_FENDER, LEFT_FRONT_FENDER, RIGHT_REAR_FENDER,',
'            LEFT_REAR_FENDER, RIGHT_FRONT_DOOR, LEFT_FRONT_DOOR, RIGHT_REAR_DOOR, LEFT_REAR_DOOR, THE_HOOD, THE_ROOF, THE_TRUNK, ',
'            ENGINE_NOISE, VALVE_LIFTERS_NOISE, ENGINE_SMOKE, ENGINE_DETACHED, AIRBAGS, VEHICLE_GLASS, FRONT_CHASSIS, REAR_CHASSIS, ',
'            FRONT_BUMPER_SUPPORT, REAR_BUMPER_SUPPORT, RADIATOR_MOUNT, HAIL_DAMAGE, PAINT_THICKNESS, SCRATCHES, FOUR_WHEEL_DRIVE, SEAT_MATERIAL',
'        ) VALUES (',
'            :P4_ID, :P4_IS_CAR_WORKING, :P4_IS_CAR_HAVE_KEY, :P4_TRANSMISSION_TYPE, :P4_OODO_METER, :P4_CAR_NAME, :P4_PLATE_NUMBER_FROM_INSPECTOR, :P4_NOTES, :P4_RIGHT_FRONT_FENDER, :P4_LEFT_FRONT_FENDER, :P4_RIGHT_REAR_FENDER,',
'            :P4_LEFT_REAR_FENDER, :P4_RIGHT_FRONT_DOOR, :P4_LEFT_FRONT_DOOR, :P4_RIGHT_REAR_DOOR, :P4_LEFT_REAR_DOOR, :P4_THE_HOOD, :P4_THE_ROOF, :P4_THE_TRUNK,',
'            :P4_ENGINE_NOISE, :P4_VALVE_LIFTERS_NOISE, :P4_ENGINE_SMOKE, :P4_ENGINE_DETACHED, :P4_AIRBAGS, :P4_VEHICLE_GLASS, :P4_FRONT_CHASSIS, :P4_REAR_CHASSIS, ',
'            :P4_FRONT_BUMPER_SUPPORT, :P4_REAR_BUMPER_SUPPORT, :P4_RADIATOR_MOUNT, :P4_HAIL_DAMAGE, :P4_PAINT_THICKNESS, :P4_SCRATCHES, :P4_FOUR_WHEEL_DRIVE, :P4_SEAT_MATERIAL',
'        )RETURNING ID INTO v_inspection_id;',
'',
'        IF SQL%ROWCOUNT = 0 THEN',
'            RAISE_APPLICATION_ERROR (-20005, ''Insert Error!'');',
'        END IF;',
'',
'    -- INSPECTION IMAGES ',
'        FOR i IN (SELECT ITEM_NAME, REPLACE(ITEM_NAME, ''P''|| PAGE_ID || ''_'') AS TYPE FROM APEX_APPLICATION_PAGE_ITEMS WHERE APPLICATION_ID = :APP_ID AND PAGE_ID = :APP_PAGE_ID AND DISPLAY_AS NOT IN (''Hidden'', ''Display Only'')  AND ITEM_NAME NOT LIKE '''
||'%_COMMENT%'') LOOP',
'        ',
'            SELECT COUNT(1)',
'              INTO v_rows_count_inspection_images',
'              FROM APEX_COLLECTIONS ',
'             WHERE COLLECTION_NAME = ''INSPECTION_IMAGES''',
'               AND c003 = i.TYPE',
'               AND c004 = :P4_ID;',
'',
'            IF v_rows_count_inspection_images > 0 THEN',
'                FOR j IN (SELECT c001 AS FILE_NAME, c002 AS MIME_TYPE, c003 AS TYPE, c004 AS CAR_DETAILS_ID, blob001 AS BLOB_CONTENT FROM apex_collections WHERE collection_name = ''INSPECTION_IMAGES'' AND c003 = i.TYPE AND c004 = :P4_ID) LOOP',
'                    l_file_name := TO_CHAR(get_current_date, ''YY'') ',
'                                        || DBMS_RANDOM.STRING(''x'', 8)',
'                                        || SYSTEM_CONTROLS.file_extension_by_mimetype(p_mimetype => j.MIME_TYPE);',
'',
'                    l_request_url := :LOCATION_URI || l_file_name;',
'',
'                    DBMS_CLOUD.put_object (',
'                        credential_name => :CREDENTIAL_NAME,',
'                        object_uri      => l_request_url,',
'                        contents        => j.blob_content',
'                    );',
'',
'                    l_images_urls := l_images_urls || l_request_url || '','';',
'                END LOOP;',
'            END IF; --COLLECTION > 0',
'',
'            l_images_urls := SUBSTR(l_images_urls, 1, LENGTH(l_images_urls) - 1);',
'',
'            -- COMMENT ',
'            v_item_value := V(i.ITEM_NAME);',
'            v_item_name_comment := i.ITEM_NAME || ''_COMMENT'';',
'            v_item_value_comment := V(v_item_name_comment);',
'',
'            -- SELECT COUNT(1)',
'            --   INTO v_count',
'            --   FROM INSPECTION_DETAILS ',
'            --  WHERE INSPECTION_ID = v_inspection_id',
'            --    AND ITEM_NAME = i.TYPE;',
'',
'            -- IF v_count > 0 THEN',
'            --     UPDATE INSPECTION_DETAILS',
'            --        SET COMMENT_ = v_item_value_comment,',
'            --            IMAGES_URL = l_images_urls',
'            --      WHERE INSPECTION_ID = v_inspection_id',
'            --        AND ITEM_NAME = i.TYPE;  ',
'',
'            --     IF SQL%ROWCOUNT = 0 THEN',
'            --         RAISE_APPLICATION_ERROR (-20007, ''Updating Error!'');',
'            --     END IF;',
'            -- ELSE',
'            --     -- comment not null or images not null *******',
'            --     IF l_images_urls IS NOT NULL',
'            --        OR (',
'            --            INSTR('','' || :P4_ACCEPTABLE_STATUS_IDS || '','', '','' || v_item_value || '','') = 0',
'            --            AND v_item_value_comment IS NOT NULL',
'            --        )',
'            --     THEN',
'',
'            --         INSERT INTO INSPECTION_DETAILS (INSPECTION_ID, ITEM_NAME, COMMENT_, IMAGES_URL)',
'            --                             VALUES (v_inspection_id, i.TYPE, v_item_value_comment, l_images_urls);',
'',
'            --         IF SQL%ROWCOUNT = 0 THEN',
'            --             RAISE_APPLICATION_ERROR (-20008, ''Insertion Error!'');',
'            --         END IF;',
'            --     END IF;',
'            -- END IF;',
'',
'',
'            -- ## DEBUGING ##',
'            apex_debug.message(''## BEFORE ## Item: %s'', i.item_name);',
'            apex_debug.message(''## BEFORE ## Images: %s'', l_images_urls);',
'            apex_debug.message(''## BEFORE ## Comment: %s Value: %s'', v_item_name_comment, v_item_value_comment);',
'',
'            SELECT COUNT(1)',
'              INTO v_count',
'              FROM INSPECTION_DETAILS ',
'             WHERE INSPECTION_ID = v_inspection_id ',
'               AND ITEM_NAME = i.TYPE;',
'',
'            IF l_images_urls IS NOT NULL',
'               OR (',
'                   INSTR('','' || :P4_ACCEPTABLE_STATUS_IDS || '','', '','' || v_item_value || '','') = 0',
'                   AND v_item_value_comment IS NOT NULL',
'               )',
'               OR (',
'                   INSTR('','' || :P4_ACCEPTABLE_STATUS_IDS || '','', '','' || v_item_value || '','') <> 0',
'                   AND v_count > 0',
'               )',
'            THEN',
'                -- SELECT COUNT(1)',
'                --   INTO v_count',
'                --   FROM INSPECTION_DETAILS ',
'                --  WHERE INSPECTION_ID = v_inspection_id ',
'                --    AND ITEM_NAME = i.TYPE;',
'',
'                IF v_count > 0 THEN',
'                    UPDATE INSPECTION_DETAILS',
'                       SET COMMENT_ = v_item_value_comment,',
'                           IMAGES_URL = l_images_urls',
'                     WHERE INSPECTION_ID = v_inspection_id ',
'                       AND ITEM_NAME = i.TYPE;  ',
'',
'                    IF SQL%ROWCOUNT = 0 THEN',
'                        RAISE_APPLICATION_ERROR (-20007, ''Updating Error!'');',
'                    END IF;',
'                ELSE',
'                    INSERT INTO INSPECTION_DETAILS (INSPECTION_ID, ITEM_NAME, COMMENT_, IMAGES_URL)',
'                                        VALUES (v_inspection_id , i.TYPE, v_item_value_comment, l_images_urls);',
'',
'                    IF SQL%ROWCOUNT = 0 THEN',
'                        RAISE_APPLICATION_ERROR (-20008, ''Insertion Error!'');',
'                    END IF;',
'                END IF;',
'            END IF;',
'',
'            l_images_urls := NULL;',
'            v_item_value_comment := NULL;',
'',
'',
'            -- ## After',
'            apex_debug.message(''## AFTER ## Item: %s'', i.item_name);',
'            apex_debug.message(''## AFTER ## Images: %s'', l_images_urls);',
'            apex_debug.message(''## AFTER ## Comment: %s Value: %s'', v_item_name_comment, v_item_value_comment);',
'        END LOOP;',
'        ',
'        IF APEX_COLLECTION.collection_exists(''INSPECTION_IMAGES'') THEN',
'            APEX_COLLECTION.TRUNCATE_COLLECTION (p_collection_name => ''INSPECTION_IMAGES'');',
'        END IF; ',
'        ',
'        IF APEX_COLLECTION.collection_exists(''INSPECTION_IMAGES_FROM_TABLE'') THEN',
'            APEX_COLLECTION.TRUNCATE_COLLECTION (p_collection_name => ''INSPECTION_IMAGES_FROM_TABLE'');',
'        END IF;',
'',
'        UPDATE SELLER_ASSIGNED_FILES_DETAILS',
'           SET INSPECTION_STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''done'', p_lookup_code => ''assigned_files_status''),',
'               IS_CHECKED = 1',
'         WHERE ID = :P4_ID;',
'',
'        IF SQL%ROWCOUNT = 0 THEN',
'            RAISE_APPLICATION_ERROR (-20007, ''Updating Error!'');',
'        END IF;',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(178622300726804171)
