wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(71187852509982609)
,p_process_sequence=>30
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Get images'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_urls_split     APEX_T_VARCHAR2;',
'    v_count          NUMBER;',
'    v_is_editable    NUMBER;',
'    v_car_details_id NUMBER;',
'',
'BEGIN ',
'    -- RAISE_APPLICATION_ERROR (-20005, :P4_INSPECTION_ID || '' / Update Error! : '' || :P4_IS_EDITABLE );',
'    SELECT COUNT(1) ',
'      INTO v_count',
'      FROM INSPECTION_DETAILS ',
'     WHERE INSPECTION_ID = :P4_INSPECTION_ID',
'       AND IMAGES_URL IS NOT NULL;',
'',
'    IF v_count > 0 THEN',
'        SELECT CAR_DETAILS_ID',
'          INTO v_car_details_id',
'          FROM INSPECTION',
'         WHERE ID = :P4_INSPECTION_ID;',
'         ',
'        IF APEX_COLLECTION.collection_exists(''INSPECTION_IMAGES_FROM_TABLE'') THEN',
'            APEX_COLLECTION.TRUNCATE_COLLECTION (p_collection_name => ''INSPECTION_IMAGES_FROM_TABLE'');',
'        END IF;',
'        ',
'        FOR i IN ( SELECT ITEM_NAME, IMAGES_URL FROM INSPECTION_DETAILS WHERE INSPECTION_ID = :P4_INSPECTION_ID AND IMAGES_URL IS NOT NULL) LOOP ',
'',
'            v_urls_split := APEX_STRING.split ( p_str => i.IMAGES_URL, p_sep => '','' );',
'',
'            FOR j IN 1 .. v_urls_split.count LOOP',
'                IF NOT APEX_COLLECTION.collection_exists(''INSPECTION_IMAGES_FROM_TABLE'') THEN',
'                   APEX_COLLECTION.create_collection(''INSPECTION_IMAGES_FROM_TABLE'');',
'                   APEX_COLLECTION.add_member (',
'                       p_collection_name => ''INSPECTION_IMAGES_FROM_TABLE'',',
'                       p_c001 => i.ITEM_NAME,',
'                       p_c002 => v_urls_split(j),',
'                       p_c003 => v_car_details_id',
'                   );',
'               ELSE',
'                   APEX_COLLECTION.add_member (',
'                       p_collection_name => ''INSPECTION_IMAGES_FROM_TABLE'',',
'                       p_c001 => i.ITEM_NAME,',
'                       p_c002 => v_urls_split(j),',
'                       p_c003 => v_car_details_id',
'                   );',
'                END IF;',
'            END LOOP;',
'        END LOOP;',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT 1',
'  FROM INSPECTION ',
' WHERE CAR_DETAILS_ID = :P4_ID',
'   AND IS_EDITABLE = 1;'))
,p_process_when_type=>'EXISTS'
,p_internal_uid=>37345401976991423
,p_process_comment=>':P16_IS_CHECKED = 1 AND :P16_IS_EDITABLE = 1'
);
end;
