,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT i.id,',
'       i.offer_id,',
'       i.offer_amount,',
'       i.tax_pct,',
'       i.tax_amount,',
'       i.company_pct,',
'       i.total_amount,',
'       i.status,',
'       i.agent_receipt_url,',
'       i.invoice_url,',
'       CASE WHEN i.invoice_url IS NOT NULL THEN',
'          ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'      ELSE ''''',
'      END AS invoice_url_class,',
'       r.product_name,',
'       null AS upload_invoice',
'  FROM transportation_invoices i,',
'       transportation_requests r,',
'       transportation_request_offers o',
' WHERE i.offer_id = o.id',
'   AND r.id = o.request_id',
'   AND agent_receipt_url IS NOT NULL',
' ORDER BY id DESC;'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_page_header=>'Assigned Files Container'
);
