 p_id=>wwv_flow_imp.id(213313240025699415)
,p_name=>'Inspection'
,p_template=>wwv_flow_imp.id(217793025397592380)
,p_display_sequence=>45
,p_region_template_options=>'#DEFAULT#:t-Region--removeHeader js-removeLandmark:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-AVPList--rightAligned:t-Report--hideNoPagination'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT m.ID,',
'       (SELECT PERSONAL_NAME FROM APP_USERS WHERE ID = m.CHECKER_USER_ID) AS AGENT_NAME,',
'       (SELECT count(1) FROM seller_assigned_files_details WHERE master_id = m.id) AS VEHICLES_COUNT,',
'       (SELECT COUNT(1) FROM SELLER_ASSIGNED_FILES_DETAILS WHERE MASTER_ID = m.id AND INSPECTION_STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''done'', p_lookup_code => ''assigned_files_status'')) AS COMPLETED_VEHICLES,',
'       (SELECT count(1) * 50 FROM seller_assigned_files_details WHERE master_id = m.id AND INSPECTION_STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''done'', p_lookup_code => ''assigned_files_status'')) AS INSPECTION_COST,',
'       m.AGENT_INSPECTION_PAYMENT_DOCUMENT,',
'       CASE',
'        WHEN m.AGENT_INSPECTION_PAYMENT_DOCUMENT IS NOT NULL THEN',
'          ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'       ELSE ''''',
'       END AS AGENT_INSPECTION_PAYMENT_DOCUMENT_CLASS,',
'       m.INSPECTION_PAYMENT_DOCUMENT,',
'       CASE',
'        WHEN m.INSPECTION_PAYMENT_DOCUMENT IS NOT NULL THEN',
'          ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'       ELSE ''''',
'       END AS INSPECTION_PAYMENT_DOCUMENT_CLASS',
'  FROM SELLER_ASSIGNED_FILES_MASTER m',
'WHERE m.ID = :P6_ID;'))
,p_display_when_condition=>'P6_TYPE'
,p_display_when_cond2=>'inspection'
,p_display_condition_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P6_ID'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(217856056487592421)
