wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(30039001434928676)
,p_event_id=>wwv_flow_imp.id(30038048427928675)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'(function setupImagePreview() {',
'  const dropzones = [',
'    { boxId: ''P7_FRONT_RIGHT_CORNER_DROPZONE'', inputId: ''P7_FRONT_RIGHT_CORNER'' },',
'    { boxId: ''P7_FRONT_LEFT_CORNER_DROPZONE'', inputId: ''P7_FRONT_LEFT_CORNER'' },',
'    { boxId: ''P7_BACK_RIGHT_CORNER_DROPZONE'', inputId: ''P7_BACK_RIGHT_CORNER'' },',
'    { boxId: ''P7_BACK_LEFT_CORNER_DROPZONE'', inputId: ''P7_BACK_LEFT_CORNER'' },',
'    { boxId: ''P7_FRONT_SEATS_DROPZONE'', inputId: ''P7_FRONT_SEATS'' },',
'    { boxId: ''P7_BACK_SEATS_DROPZONE'', inputId: ''P7_BACK_SEATS'' },',
'    { boxId: ''P7_ODO_METER_DROPZONE'', inputId: ''P7_ODO_METER'' },',
'    { boxId: ''P7_PICKUP_IMAGE_ON_TRUCK_DROPZONE'', inputId: ''P7_PICKUP_IMAGE_ON_TRUCK'' }',
'  ];',
'',
'  function showPreview(boxId, file) {',
'    const box = document.getElementById(boxId);',
'    if (!box || !file) return;',
'',
'    const imgUrl = URL.createObjectURL(file);',
'    box.style.backgroundImage = `url(''${imgUrl}'')`;',
'    box.style.backgroundSize = ''contain'';',
'    box.style.backgroundPosition = ''center'';',
'    box.style.backgroundRepeat = ''no-repeat'';',
'    box.classList.add(''has-image'');',
'  }',
'',
'  function watchInput(boxId, inputId) {',
'    const box = document.getElementById(boxId);',
'    if (!box) return;',
'',
'    const container = box.closest(''.a-FileDrop'');',
'    if (!container) return;',
'',
'    const observer = new MutationObserver(() => {',
'      const input = document.getElementById(inputId);',
'      if (input && input.files && input.files[0]) {',
'        showPreview(boxId, input.files[0]);',
'      }',
'    });',
'',
'    observer.observe(container, { childList: true, subtree: true });',
'  }',
'',
'  dropzones.forEach(({ boxId, inputId }) => {',
'    watchInput(boxId, inputId);',
'  });',
'})();',
''))
);
