wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(190869441280889175)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Upload Towing Truck Image'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_file_names        APEX_T_VARCHAR2;',
'    l_file              APEX_APPLICATION_TEMP_FILES%ROWTYPE;',
'    l_file_name         VARCHAR2(255);',
'    l_request_url	    VARCHAR2(32767);',
'    l_result	        CLOB;',
'    l_request_filename	VARCHAR2(500);',
'    l_inner_folder  	VARCHAR2(500);',
'BEGIN',
'    l_file_names := apex_string.SPLIT (',
'                        p_str => :P8_TOWING_TRUCK,',
'                        p_sep => '':'' );',
'',
'    -- IF l_file_names.count = 0 THEN',
unistr('    --     RAISE_APPLICATION_ERROR(-20001, ''\064A\062C\0628 \0639\0644\064A\0643 \0631\0641\0639 \0627\0644\062A\0642\0631\064A\0631 \0627\0644\062E\0627\0635 \0628\0643!'');'),
'    -- END IF;',
'',
'    IF l_file_names.count > 0 THEN',
'        SELECT *',
'          INTO l_file',
'          FROM APEX_APPLICATION_TEMP_FILES',
'         WHERE NAME = :P8_TOWING_TRUCK;',
'',
'        l_file_name := TO_CHAR(get_current_date, ''YY'') ',
'                            || DBMS_RANDOM.STRING(''x'', 8)',
'                            || SYSTEM_CONTROLS.file_extension_by_mimetype(p_mimetype => l_file.MIME_TYPE);',
'',
'        l_request_url := :LOCATION_URI || l_file_name;',
'',
'        DBMS_CLOUD.put_object (',
'            credential_name => :CREDENTIAL_NAME,',
'            object_uri      => l_request_url,',
'            contents        => l_file.blob_content',
'        );',
'',
'        :P8_TOWING_TRUCK_URL := l_request_url;',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(190868821753889169)
,p_internal_uid=>29102063007261634
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(190869680036889178)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Insert /Update Offer'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE ',
'    v_count NUMBER;',
'BEGIN ',
'',
'    SELECT COUNT(1)',
'      INTO v_count',
'      FROM TRANSPORTATION_REQUEST_OFFERS',
'     WHERE AGENT_ID = :P8_AGENT_ID',
'           AND REQUEST_ID = :P8_REQUEST_ID; ',
'',
'    IF v_count = 0 THEN',
'',
'        insert into TRANSPORTATION_REQUEST_OFFERS (AGENT_ID, REQUEST_ID, TOWING_TRUCK_TYPE, TOWING_TRUCK_URL, OFFERED_PRICE, IS_ACTIVE,AGENT_NOTES,EXPECTED_DELIVERY_TIME)',
'             values ( AGENTS_PKG.agent_id_by_user_id (p_user_id => :P_USER_ID), :P8_REQUEST_ID, :P8_TOWING_TRUCK_TYPE, :P8_TOWING_TRUCK_URL, :P8_OFFERED_PRICE, 1,:P8_NOTES,:P8_EXPECTED_DELIVEY_TIME);',
'       ',
'        IF SQL%ROWCOUNT = 0 THEN',
'        RAISE_APPLICATION_ERROR(-20001, ''Offer Creation Error'');',
'        END IF;',
'    ELSE',
'',
'        UPDATE TRANSPORTATION_REQUEST_OFFERS',
'           SET TOWING_TRUCK_TYPE = :P8_TOWING_TRUCK_TYPE, ',
'               TOWING_TRUCK_URL = :P8_TOWING_TRUCK_URL, ',
'               OFFERED_PRICE = :P8_OFFERED_PRICE,',
'               AGENT_NOTES = :P8_NOTES,',
'               EXPECTED_DELIVERY_TIME = :P8_EXPECTED_DELIVEY_TIME',
'           WHERE REQUEST_ID = :P8_REQUEST_ID -- why need this ?',
'            AND ID = :P8_ID;',
'',
'        IF SQL%ROWCOUNT = 0 THEN',
'        RAISE_APPLICATION_ERROR(-20002, ''Offer Updating Error'');',
'        END IF;',
'    END IF; ',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Error adding offer'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(190868821753889169)
,p_process_success_message=>'Offer added.'
,p_internal_uid=>29102301763261637
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(195716388412775089)
,p_process_sequence=>50
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'withdrawal'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'UPDATE TRANSPORTATION_REQUEST_OFFERS',
'   SET IS_WITHDRAWAL =  1',
' WHERE ID = :P8_ID ',
'       AND REQUEST_ID = :P8_REQUEST_ID ;',
'',
'-- IF SQL%ROWCOUNT = 0 THEN ',
'--      RAISE_APPLICATION_ERROR(-20001, ''withdrawing Error '');',
'-- END IF;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Error Withdrawing Offer.'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
