wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(192246051409029088)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Offer details'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT ID, AGENT_ID, REQUEST_ID, TOWING_TRUCK_TYPE, TOWING_TRUCK_URL, OFFERED_PRICE,EXPECTED_DELIVERY_TIME,AGENT_NOTES',
'      INTO :P8_ID, :P8_AGENT_ID, :P8_REQUEST_ID, :P8_TOWING_TRUCK_TYPE, :P8_TOWING_TRUCK_URL, :P8_OFFERED_PRICE,:P8_EXPECTED_DELIVEY_TIME,:P8_NOTES',
'      FROM TRANSPORTATION_REQUEST_OFFERS',
'     WHERE REQUEST_ID = :P8_REQUEST_ID',
'       AND AGENT_ID = AGENTS_PKG.agent_id_by_user_id (p_user_id => :P_USER_ID)',
'       AND IS_WITHDRAWAL = 0;',
'',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN     ',
'             :P8_ID                := NULL;',
'             :P8_AGENT_ID          := NULL;',
'             :P8_REQUEST_ID        := NULL;',
'             :P8_TOWING_TRUCK_TYPE := NULL;',
'             :P8_TOWING_TRUCK_URL  := NULL;',
'             :P8_OFFERED_PRICE     := NULL;',
'             :P8_NOTES             := NULL;',
'             :P8_EXPECTED_DELIVEY_TIME := null;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>30478673135401547
);
end;
