wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(192243254108029060)
,p_plug_name=>'<span class="fa fa-server"></span> All Requests'
,p_parent_plug_id=>wwv_flow_imp.id(190870089088889182)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(217785771929592374)
,p_plug_display_sequence=>60
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT r.ID,',
'       r.USER_NAME AS USER_ID,',
'       r.TRUCK_TYPE,',
'       r.PRODUCT_NAME,',
'       r.CREATED_DATE,',
'       r.STATUS,',
'       r.delivery_city_id,',
'       r.delivery_neighborhood,',
'       r.location,',
'       p.OFFERED_PRICE,',
'       p.IS_WITHDRAWAL,',
'       p.IS_APPROVED,',
'       p.AGENT_ID,',
'       CASE',
unistr('        WHEN p.IS_SELECTED = 0  THEN DECODE(NVL(:P_LANG, ''en''), ''ar'', ''\0644\0645 \064A\062A\0645 \0627\062E\062A\064A\0627\0631 \0627\0644\0639\0631\0636'', ''The offer was not selected'') '),
unistr('        WHEN p.IS_WITHDRAWAL = 1 THEN DECODE(NVL(:P_LANG, ''en''), ''ar'', ''\062A\0645 \0627\0644\0627\0646\0633\062D\0627\0628'', ''Withdrawal'')'),
'       END REASON',
'    --    ''<a href=https://maps.google.com/?q='' || r.PICKUP_LONGITUDE || '','' || r.PICKUP_LATITUDE || '' target="_blank">',
'    --         <span class="fa fa-map-marker-o pickup_destination"  aria-hidden="true"></span>',
'    --     </a>'' as pickup_destination,',
'    --    ''<a href=https://maps.google.com/?q='' || r.ARRIVAL_LONGITUDE || '','' || r.ARRIVAL_LATITUDE || '' target="_blank">',
'    --         <span class="fa fa-map-marker-o pickup_destination"  aria-hidden="true"></span>',
'    --     </a>'' as arrival_destination,',
'  FROM TRANSPORTATION_REQUESTS r,',
'       TRANSPORTATION_REQUEST_OFFERS p ',
' WHERE r.ID = p.REQUEST_ID',
'    --    AND LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => r.STATUS) NOT IN ( ''delivered'' ) ',
'    --    AND r.IS_DONE = 1',
'    AND (p.AGENT_ID =  AGENTS_PKG.agent_id_by_user_id (p_user_id => :P_USER_ID)) -- OBJECT_VALUE',
'    --    AND ( p.IS_APPROVED = 0 OR p.IS_SELECTED = 0 OR p.IS_WITHDRAWAL = 1 )'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
