wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(192820580779874843)
,p_plug_name=>'<span class="fa fa-server-check"></span> Done Requests'
,p_parent_plug_id=>wwv_flow_imp.id(190870089088889182)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(217785771929592374)
,p_plug_display_sequence=>50
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT r.ID,',
'       r.USER_NAME as USER_ID,',
'       r.TRUCK_TYPE,',
'       r.PRODUCT_NAME,',
'       r.CREATED_DATE,',
'       r.STATUS,',
'       r.delivery_city_id,',
'       r.delivery_neighborhood,',
'       r.location,',
'       p.id AS offer_id,',
'       p.OFFERED_PRICE,',
'       i.AGENT_RECEIPT_URL,',
'       CASE WHEN i.AGENT_RECEIPT_URL IS NOT NULL THEN',
'          ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'      ELSE ''''',
'      END AS AGENT_RECEIPT_URL_CLASS,',
'       i.INVOICE_URL,',
'       CASE WHEN i.INVOICE_URL IS NOT NULL THEN',
'          ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'      ELSE ''''',
'      END AS INVOICE_URL_CLASS,',
'       null AS payment_request',
'    --    ''<a href=https://maps.google.com/?q='' || r.PICKUP_LONGITUDE || '','' || r.PICKUP_LATITUDE || '' target="_blank">',
'    --         <span class="fa fa-map-marker-o pickup_destination"  aria-hidden="true"></span>',
'    --     </a>'' as pickup_destination,',
'    --    ''<a href=https://maps.google.com/?q='' || r.ARRIVAL_LONGITUDE || '','' || r.ARRIVAL_LATITUDE || '' target="_blank">',
'    --         <span class="fa fa-map-marker-o pickup_destination"  aria-hidden="true"></span>',
'    --     </a>'' as arrival_destination,',
'  FROM TRANSPORTATION_REQUESTS r,',
'       TRANSPORTATION_REQUEST_OFFERS p,',
'       TRANSPORTATION_INVOICES i',
' WHERE r.ID = p.REQUEST_ID',
'   AND p.id = i.offer_id',
'   AND LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => r.STATUS) = ( ''delivered'' ) ',
'   AND r.IS_PICKUP_CONFIRM = 1',
'   AND r.IS_ARRIVAL_CONFIRM = 1',
'   AND r.IS_AGENT_PICKUP_CONFIRM = 1',
'   AND r.IS_AGENT_ARRIVAL_CONFIRM = 1',
'   AND r.IS_DONE = 1',
'   AND (p.AGENT_ID =  AGENTS_PKG.agent_id_by_user_id (p_user_id => :P_USER_ID)) -- OBJECT_VALUE',
'   AND r.IS_AGENT_ARRIVAL_CONFIRM = 1',
'   AND p.IS_SELECTED = 1',
'   AND p.IS_APPROVED = 1',
'   AND p.IS_WITHDRAWAL = 0'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
