wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(277474922760311980)
,p_plug_name=>'<span class="fa fa-server-new"></span> New Requests '
,p_parent_plug_id=>wwv_flow_imp.id(190870089088889182)
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(217785771929592374)
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT r.ID,',
'       r.USER_ID,',
'       r.TRUCK_TYPE,',
'       r.PRODUCT_NAME,',
'       r.MAKE,',
'       r.MODEL,',
'       r.YEAR,',
'       r.PLATE_NUMBER,',
'       r.VIN_NUMBER,',
'       r.SERIAL_NUMBER,',
'       r.PRODUCT_MAP_URL,',
'       ''<a href=https://maps.google.com/?q='' || r.PICKUP_LONGITUDE || '','' || r.PICKUP_LATITUDE || '' target="_blank">',
'            <span class="fa fa-map-marker-o pickup_destination"  aria-hidden="true"></span>',
'        </a>'' as pickup_destination,',
'       ''<a href=https://maps.google.com/?q='' || r.ARRIVAL_LONGITUDE || '','' || r.ARRIVAL_LATITUDE || '' target="_blank">',
'            <span class="fa fa-map-marker-o pickup_destination"  aria-hidden="true"></span>',
'        </a>'' as arrival_destination,',
'    --    CASE',
'    --     WHEN r.PICKUP_DESTINATION IS NOT NULL THEN',
'    --         ''<span class="fa fa-map-marker-o" aria-hidden="true"></span>''',
'    --     ELSE ''''',
'    --     END AS PICKUP_DESTINATION_CLASS,',
'    --    r.PICKUP_DESTINATION,',
'    --    CASE',
'    --     WHEN r.ARRIVAL_DESTINATION IS NOT NULL THEN',
'    --         ''<span class="fa fa-map-marker-o" aria-hidden="true"></span>''',
'    --     ELSE ''''',
'    --     END AS ARRIVAL_DESTINATION_CLASS,',
'       r.STATUS,',
'       r.IS_AGENT_PICKUP_CONFIRM,',
'       r.IS_AGENT_ARRIVAL_CONFIRM,',
'       r.IS_PICKUP_CONFIRM,',
'       r.IS_ARRIVAL_CONFIRM,',
'       r.CREATED_DATE,',
'       r.CREATED_BY,',
'       r.PICKUP_DATE,',
'       r.REQUEST_NOTES,',
'       r.delivery_city_id,',
'       r.delivery_neighborhood,',
'       CASE',
'          WHEN r.LOCATION IS NOT NULL',
'               AND REGEXP_LIKE (r.LOCATION, ''^https?://'')',
'          THEN',
'               ''<a href="''            || apex_escape.html (r.LOCATION)',
unistr('            || ''" target="_blank" class="map-link">\0639\0631\0636 \0639\0644\0649 \0627\0644\062E\0631\064A\0637\0629</a>'''),
'          WHEN r.LOCATION IS NOT NULL',
'          THEN apex_escape.html (r.LOCATION)      -- plain text, escaped',
'          ELSE NULL',
'        END AS location,',
'       NULL AS OFFER,',
'       NULL car_info,',
'       (',
'           SELECT o.ID ',
'            FROM TRANSPORTATION_REQUEST_OFFERS o',
'            WHERE o.REQUEST_ID = r.ID ',
'              AND o.AGENT_ID = AGENTS_PKG.agent_id_by_user_id(:P_USER_ID)',
'              AND o.IS_WITHDRAWAL = 0',
'              AND o.IS_APPROVED = 0',
'              AND o.IS_SELECTED = 0',
'            FETCH FIRST 1 ROWS ONLY',
'        ) AS OFFER_ID,',
'',
'        CASE ',
'            WHEN (',
'                SELECT COUNT(*) ',
'                FROM TRANSPORTATION_REQUEST_OFFERS o',
'                WHERE o.REQUEST_ID = r.ID ',
'                  AND o.AGENT_ID = AGENTS_PKG.agent_id_by_user_id(:P_USER_ID)',
'                  AND o.IS_WITHDRAWAL = 0',
'                  AND o.IS_APPROVED = 0',
'                  AND o.IS_SELECTED = 0',
unistr('            ) > 0 THEN decode(:P_LANG,''en'', ''Update Offer'', ''\062A\0639\062F\064A\0644 \0627\0644\0639\0631\0636'')'),
unistr('            ELSE decode (:P_LANG, ''en'', ''Add Offer'', ''\0627\0636\0627\0641\0629 \0639\0631\0636'')'),
'        END AS OFFER_TEXT',
'',
'  from TRANSPORTATION_REQUESTS r--,',
'       --TRANSPORTATION_REQUEST_OFFERS p ',
' WHERE LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => r.STATUS) = ''waiting_offers''',
'    --    AND r.ID  = p.REQUEST_ID (+)',
'    --    AND p.AGENT_ID = AGENTS_PKG.agent_id_by_user_id (p_user_id => :P_USER_ID) ',
'    --    AND p.IS_WITHDRAWAL = 0',
'    --    AND p.IS_APPROVED = 0',
'    --    AND p.IS_SELECTED = 0',
'       ORDER BY CREATED_DATE DESC'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_page_header=>'Assigned Files Container'
);
