wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(197042355540581144)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'UPLOAD IMAGE BRFORE LOADING ( PICKUP )'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_file_names        APEX_T_VARCHAR2;',
'    l_file              APEX_APPLICATION_TEMP_FILES%ROWTYPE;',
'    l_file_name         VARCHAR2(255);',
'    l_request_url	    VARCHAR2(32767);',
'    l_result	        CLOB;',
'    l_request_filename	VARCHAR2(500);',
'    l_inner_folder  	VARCHAR2(500);',
'BEGIN',
'',
'    select *',
'      into l_file',
'      from apex_application_temp_files',
'     where name = :P11_IMAGE_BEFORE_LOADING;',
'   ',
'    ',
'    l_file_name := TO_CHAR(get_current_date, ''YY'') ',
'                        || DBMS_RANDOM.STRING(''x'', 8)',
'                        || SYSTEM_CONTROLS.file_extension_by_mimetype(p_mimetype => l_file.MIME_TYPE);',
'',
'    l_file_name := TO_CHAR(get_current_date, ''YY'') ',
'                        || DBMS_RANDOM.STRING(''x'', 8)',
'                        || SYSTEM_CONTROLS.file_extension_by_mimetype(p_mimetype => l_file.MIME_TYPE);',
'',
'    l_request_url := :LOCATION_URI||''/b/transportation/o/''||l_file_name;',
'     ',
'     DBMS_CLOUD.put_object (',
'        credential_name => :CREDENTIAL_NAME,',
'        object_uri      => l_request_url,',
'        contents        => l_file.blob_content',
'        );',
'',
'    INSERT INTO TRANSPORTATION_REQUEST_DOCUMENTS ( REQUEST_ID, DOCUMENT_URL, TYPE, IS_ACTIVE )',
'            VALUES (:P11_REQUEST_ID, l_request_url, LOOKUPS_MNT.lookup_detail_id_by_code(p_lookup_detail_code => ''transportation_pickup'', p_lookup_code => ''transportation_image_type''), 1);',
'    -- :P11_IMAGE_BEFORE_LOADING_URL := l_request_url;',
'     ',
'    exception',
'        when no_data_found then',
unistr('            RAISE_APPLICATION_ERROR(-20001, '' \064A\062C\0628 \0639\0644\064A\0643 \0631\0641\0639 \0627\0644\0635\0648\0631\0629!'');'),
'        when others then',
unistr('            raise_application_error(-20001,''\062E\0637\0623 \0641\064A \062A\062D\0645\064A\0644 \0627\0644\0635\0648\0631\0629. ''||SQLERRM);'),
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'#SQLERRM_TEXT#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_type=>'NEVER'
,p_internal_uid=>35274977266953603
);
