,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH VEHICLES_COUNT AS (',
'    SELECT MASTER_ID, count(1) AS VEHICLES_COUNT',
'      FROM  SELLER_ASSIGNED_FILES_DETAILS',
'      GROUP BY MASTER_ID',
'),',
'PHOTOGRAPHY_COMPLETED_VEHICLES AS (',
'    SELECT MASTER_ID, count(1) AS COMPLETED_COUNT',
'      FROM SELLER_ASSIGNED_FILES_DETAILS',
'     WHERE STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''done'', p_lookup_code => ''assigned_files_status'')',
'      GROUP BY MASTER_ID',
'),',
'INSPECTION_COMPLETED_VEHICLES AS (',
'    SELECT MASTER_ID, count(1) AS COMPLETED_COUNT',
'      FROM SELLER_ASSIGNED_FILES_DETAILS',
'     WHERE INSPECTION_STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''done'', p_lookup_code => ''assigned_files_status'')',
'      GROUP BY MASTER_ID',
')',
'',
'SELECT (SELECT PERSONAL_NAME FROM APP_USERS WHERE ID = m.USER_ID) AS AGENT_NAME,',
unistr('        DECODE(nvl(:P_LANG, ''ar''), ''en'', ''Photographer'', ''\0645\0635\0648\0631'') AS TYPE,'),
'        NAME,',
'        c.VEHICLES_COUNT as VEHICLES_COUNT,',
'        p.COMPLETED_COUNT as COMPLETED_VEHICLES,',
'        p.COMPLETED_COUNT * 35  AS COST,',
'       AGENT_PHOTOGRAPHY_PAYMENT_DOCUMENT AS AGENT_PAYMENT_DOCUMENT,',
'       CASE',
'        WHEN AGENT_PHOTOGRAPHY_PAYMENT_DOCUMENT IS NOT NULL THEN',
'            ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'        ELSE ''''',
'        END AS AGENT_PAYMENT_DOCUMENT_CLASS,',
'       PHOTOGRAPHY_TRANSFERRED_AMOUNT AS TRANSFERRED_AMOUNT,',
'       PHOTOGRAPHY_PAYMENT_DOCUMENT AS PAYMENT_DOCUMENT,',
'       CASE',
'        WHEN PHOTOGRAPHY_PAYMENT_DOCUMENT IS NOT NULL THEN',
'            ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'        ELSE ''''',
'        END AS PAYMENT_DOCUMENT_CLASS',
'  FROM SELLER_ASSIGNED_FILES_MASTER m,',
'       VEHICLES_COUNT c,',
'       PHOTOGRAPHY_COMPLETED_VEHICLES p',
' WHERE PHOTOGRAPHY_PAYMENT_DOCUMENT IS NOT NULL ',
'       and (m.USER_ID = AGENTS_PKG.user_id_by_agent_id (  p_agent_id =>  :P13_AGENT) OR :P13_AGENT IS NULL)',
'       and m.id = c.master_id',
'       and m.id = p.master_id',
'       AND IS_ACTIVE = 1',
'UNION ALL',
'SELECT (SELECT PERSONAL_NAME FROM APP_USERS WHERE ID = m.CHECKER_USER_ID) AS AGENT_NAME,',
unistr('        DECODE(nvl(:P_LANG, ''ar''), ''en'', ''Inspector'', ''\0641\0627\062D\0635'') AS TYPE,'),
'        NAME,',
'        c.VEHICLES_COUNT as VEHICLES_COUNT,',
'        i.COMPLETED_COUNT as COMPLETED_VEHICLES,',
'        i.COMPLETED_COUNT * 50 as COMPLETED_VEHICLES,',
'       AGENT_INSPECTION_PAYMENT_DOCUMENT AS AGENT_PAYMENT_DOCUMENT,',
'       CASE',
'        WHEN AGENT_INSPECTION_PAYMENT_DOCUMENT IS NOT NULL THEN',
'            ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'        ELSE ''''',
'        END AS AGENT_PAYMENT_DOCUMENT_CLASS,',
'       INSPECTION_TRANSFERRED_AMOUNT AS TRANSFERRED_AMOUNT,',
'       INSPECTION_PAYMENT_DOCUMENT AS PAYMENT_DOCUMENT,',
'       CASE',
'        WHEN INSPECTION_PAYMENT_DOCUMENT IS NOT NULL THEN',
'            ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'        ELSE ''''',
'        END AS PAYMENT_DOCUMENT_CLASS',
'  FROM SELLER_ASSIGNED_FILES_MASTER m,',
'       VEHICLES_COUNT c,',
'       INSPECTION_COMPLETED_VEHICLES i',
' WHERE INSPECTION_PAYMENT_DOCUMENT IS NOT NULL',
