,p_plug_display_sequence=>35
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT NAME,',
'       (SELECT count(1) FROM seller_assigned_files_details WHERE master_id = m.id) AS VEHICLES_COUNT,',
'       (SELECT COUNT(1) FROM SELLER_ASSIGNED_FILES_DETAILS WHERE MASTER_ID = m.id AND STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''done'', p_lookup_code => ''assigned_files_status'')) AS COMPLETED_VEHICLES,',
'       (SELECT count(1) * 35 FROM seller_assigned_files_details WHERE master_id = m.id AND STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''done'', p_lookup_code => ''assigned_files_status'')) AS COST,',
'       AGENT_PHOTOGRAPHY_PAYMENT_DOCUMENT AS AGENT_PAYMENT_DOCUMENT,',
'       CASE',
'        WHEN AGENT_PHOTOGRAPHY_PAYMENT_DOCUMENT IS NOT NULL THEN',
'            ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'        ELSE ''''',
'        END AS AGENT_PAYMENT_DOCUMENT_CLASS,',
'       PHOTOGRAPHY_TRANSFERRED_AMOUNT AS TRANSFERRED_AMOUNT,',
'       PHOTOGRAPHY_PAYMENT_DOCUMENT AS PAYMENT_DOCUMENT,',
'       CASE',
'        WHEN PHOTOGRAPHY_PAYMENT_DOCUMENT IS NOT NULL THEN',
'            ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'        ELSE ''''',
'        END AS PAYMENT_DOCUMENT_CLASS',
'  FROM SELLER_ASSIGNED_FILES_MASTER m',
' WHERE m.USER_ID = :P_USER_ID	',
'       AND PHOTOGRAPHY_PAYMENT_DOCUMENT IS NOT NULL ',
'       AND IS_ACTIVE = 1',
'UNION ALL',
'SELECT NAME,',
'       (SELECT count(1) FROM seller_assigned_files_details WHERE master_id = m.id) AS VEHICLES_COUNT,',
'       (SELECT COUNT(1) FROM SELLER_ASSIGNED_FILES_DETAILS WHERE MASTER_ID = m.id AND INSPECTION_STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''done'', p_lookup_code => ''assigned_files_status'')) AS COMPLETED_VEHICLES,',
'       (SELECT count(1) * 50 FROM seller_assigned_files_details WHERE master_id = m.id AND INSPECTION_STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''done'', p_lookup_code => ''assigned_files_status'')) AS COST,',
'       AGENT_INSPECTION_PAYMENT_DOCUMENT AS AGENT_PAYMENT_DOCUMENT,',
'       CASE',
'        WHEN AGENT_INSPECTION_PAYMENT_DOCUMENT IS NOT NULL THEN',
'            ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'        ELSE ''''',
'        END AS AGENT_PAYMENT_DOCUMENT_CLASS,',
'       INSPECTION_TRANSFERRED_AMOUNT AS TRANSFERRED_AMOUNT,',
'       INSPECTION_PAYMENT_DOCUMENT AS PAYMENT_DOCUMENT,',
'       CASE',
'        WHEN INSPECTION_PAYMENT_DOCUMENT IS NOT NULL THEN',
'            ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'        ELSE ''''',
'        END AS PAYMENT_DOCUMENT_CLASS',
'  FROM SELLER_ASSIGNED_FILES_MASTER m',
' WHERE (m.CHECKER_USER_ID = :P_USER_ID OR :P_USER_ID IN (10000, 9915, 9897))',
'       AND INSPECTION_PAYMENT_DOCUMENT IS NOT NULL ',
'       AND IS_ACTIVE = 1',
'-- -------------------------------',
'-- -------------------------------',
'-- WITH VEHICLES_COUNT AS (',
'--     SELECT MASTER_ID, count(1) AS VEHICLES_COUNT',
'--       FROM  SELLER_ASSIGNED_FILES_DETAILS',
'--       GROUP BY MASTER_ID',
'-- ),',
'-- PHOTOGRAPHY_COMPLETED_VEHICLES AS (',
'--     SELECT MASTER_ID, count(1) AS COMPLETED_COUNT',
'--       FROM SELLER_ASSIGNED_FILES_DETAILS',
'--      WHERE STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''done'', p_lookup_code => ''assigned_files_status'')',
'--       GROUP BY MASTER_ID',
'-- ),',
'-- INSPECTION_COMPLETED_VEHICLES AS (',
'--     SELECT MASTER_ID, count(1) AS COMPLETED_COUNT',
'--       FROM SELLER_ASSIGNED_FILES_DETAILS',
'--      WHERE INSPECTION_STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''done'', p_lookup_code => ''assigned_files_status'')',
'--       GROUP BY MASTER_ID',
'-- )',
'',
'-- SELECT (SELECT PERSONAL_NAME FROM APP_USERS WHERE ID = m.USER_ID) AS AGENT_NAME,',
unistr('--         DECODE(nvl(:P_LANG, ''ar''), ''en'', ''Photographer'', ''\0645\0635\0648\0631'') AS TYPE,'),
'--         m.NAME,',
'--     --    (SELECT count(1) FROM seller_assigned_files_details WHERE master_id = m.id) AS VEHICLES_COUNT,',
'--     --    (SELECT COUNT(1) FROM SELLER_ASSIGNED_FILES_DETAILS WHERE MASTER_ID = m.id AND STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''done'', p_lookup_code => ''assigned_files_status'')) AS COMPLETED_VEHICLES,',
'--     --    (SELECT count(1) * 35 FROM seller_assigned_files_details WHERE master_id = m.id AND STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''done'', p_lookup_code => ''assigned_files_status'')) AS COST,',
'--        c.VEHICLES_COUNT as VEHICLES_COUNT,',
'--        p.COMPLETED_COUNT as COMPLETED_VEHICLES,',
'--        p.COMPLETED_COUNT * 35  AS COST,',
'--        m.AGENT_PHOTOGRAPHY_PAYMENT_DOCUMENT AS AGENT_PAYMENT_DOCUMENT,',
'--        CASE',
'--         WHEN m.AGENT_PHOTOGRAPHY_PAYMENT_DOCUMENT IS NOT NULL THEN',
'--             ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'--         ELSE ''''',
'--         END AS AGENT_PAYMENT_DOCUMENT_CLASS,',
'--        m.PHOTOGRAPHY_TRANSFERRED_AMOUNT AS TRANSFERRED_AMOUNT,',
'--        m.PHOTOGRAPHY_PAYMENT_DOCUMENT AS PAYMENT_DOCUMENT,',
'--        CASE',
'--         WHEN m.PHOTOGRAPHY_PAYMENT_DOCUMENT IS NOT NULL THEN',
'--             ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
