'    --    and (m.USER_ID = :P_USER_ID OR :P_USER_ID IN (10000, 9915, 9897))',
'',
'-- UNION ALL',
'-- SELECT  (SELECT PERSONAL_NAME FROM APP_USERS WHERE ID = m.CHECKER_USER_ID) AS AGENT_NAME,',
unistr('--         DECODE(nvl(:P_LANG, ''ar''), ''en'', ''Inspector'', ''\0641\0627\062D\0635'') AS TYPE,'),
'--         m.NAME,',
'--     --    (SELECT count(1) FROM seller_assigned_files_details WHERE master_id = m.id) AS VEHICLES_COUNT,',
'--     --    (SELECT COUNT(1) FROM SELLER_ASSIGNED_FILES_DETAILS WHERE MASTER_ID = m.id AND INSPECTION_STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''done'', p_lookup_code => ''assigned_files_status'')) AS COMPLETED_VEHICLES,',
'--     --    (SELECT count(1) * 50 FROM seller_assigned_files_details WHERE master_id = m.id AND INSPECTION_STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''done'', p_lookup_code => ''assigned_files_status'')) AS COST,',
'--     c.VEHICLES_COUNT as VEHICLES_COUNT,',
'--     i.COMPLETED_COUNT as COMPLETED_VEHICLES,',
'--     i.COMPLETED_COUNT * 50 as COMPLETED_VEHICLES,',
'--        m.AGENT_INSPECTION_PAYMENT_DOCUMENT AS AGENT_PAYMENT_DOCUMENT,',
'--        CASE',
'--         WHEN m.AGENT_INSPECTION_PAYMENT_DOCUMENT IS NOT NULL THEN',
