wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(189798657297706844)
,p_plug_name=>'agents wallet'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(217785771929592374)
,p_plug_display_sequence=>45
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH VEHICLES_COUNT AS (',
'    SELECT MASTER_ID, count(1) AS VEHICLES_COUNT',
'      FROM  SELLER_ASSIGNED_FILES_DETAILS',
'      GROUP BY MASTER_ID',
'),',
'PHOTOGRAPHY_COMPLETED_VEHICLES AS (',
'    SELECT MASTER_ID, count(1) AS COMPLETED_COUNT',
'      FROM SELLER_ASSIGNED_FILES_DETAILS',
'     WHERE STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''done'', p_lookup_code => ''assigned_files_status'')',
'      GROUP BY MASTER_ID',
'),',
'INSPECTION_COMPLETED_VEHICLES AS (',
'    SELECT MASTER_ID, count(1) AS COMPLETED_COUNT',
'      FROM SELLER_ASSIGNED_FILES_DETAILS',
'     WHERE INSPECTION_STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''done'', p_lookup_code => ''assigned_files_status'')',
'      GROUP BY MASTER_ID',
')',
'',
'SELECT m.NAME,',
'       c.VEHICLES_COUNT as VEHICLES_COUNT,',
'       p.COMPLETED_COUNT as COMPLETED_VEHICLES,',
'       p.COMPLETED_COUNT * 35  AS COST,',
'       m.AGENT_PHOTOGRAPHY_PAYMENT_DOCUMENT AS AGENT_PAYMENT_DOCUMENT,',
'       CASE',
'        WHEN m.AGENT_PHOTOGRAPHY_PAYMENT_DOCUMENT IS NOT NULL THEN',
'            ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'        ELSE ''''',
'        END AS AGENT_PAYMENT_DOCUMENT_CLASS,',
'       m.PHOTOGRAPHY_TRANSFERRED_AMOUNT AS TRANSFERRED_AMOUNT,',
'       m.PHOTOGRAPHY_PAYMENT_DOCUMENT AS PAYMENT_DOCUMENT,',
'       CASE',
'        WHEN m.PHOTOGRAPHY_PAYMENT_DOCUMENT IS NOT NULL THEN',
'            ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'        ELSE ''''',
'        END AS PAYMENT_DOCUMENT_CLASS',
'  FROM SELLER_ASSIGNED_FILES_MASTER m,',
'       VEHICLES_COUNT c,',
'       PHOTOGRAPHY_COMPLETED_VEHICLES p',
' WHERE PHOTOGRAPHY_PAYMENT_DOCUMENT IS NOT NULL ',
'       AND IS_ACTIVE = 1',
'       and m.id = c.master_id',
'       and m.id = p.master_id',
'       and (m.USER_ID = :P_USER_ID OR :P_USER_ID IN (10000, 9915, 9897))',
'UNION ALL',
'SELECT  m.NAME,',
'        c.VEHICLES_COUNT as VEHICLES_COUNT,',
'        i.COMPLETED_COUNT as COMPLETED_VEHICLES,',
'        i.COMPLETED_COUNT * 50 as COMPLETED_VEHICLES,',
'        m.AGENT_INSPECTION_PAYMENT_DOCUMENT AS AGENT_PAYMENT_DOCUMENT,',
'       CASE',
'        WHEN m.AGENT_INSPECTION_PAYMENT_DOCUMENT IS NOT NULL THEN',
'            ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'        ELSE ''''',
'        END AS AGENT_PAYMENT_DOCUMENT_CLASS,',
'        m.INSPECTION_TRANSFERRED_AMOUNT AS TRANSFERRED_AMOUNT,',
'        m.INSPECTION_PAYMENT_DOCUMENT AS PAYMENT_DOCUMENT,',
'       CASE',
'        WHEN m.INSPECTION_PAYMENT_DOCUMENT IS NOT NULL THEN',
'            ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'        ELSE ''''',
'        END AS PAYMENT_DOCUMENT_CLASS',
'  FROM SELLER_ASSIGNED_FILES_MASTER m,',
'       VEHICLES_COUNT c,',
'       INSPECTION_COMPLETED_VEHICLES i',
' WHERE INSPECTION_PAYMENT_DOCUMENT IS NOT NULL ',
'       AND IS_ACTIVE = 1',
'       and m.id = c.master_id',
'       and m.id = i.master_id',
'       and (m.CHECKER_USER_ID = :P_USER_ID OR :P_USER_ID IN (10000, 9915, 9897,10621))'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
