wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(71189216741982622)
,p_plug_name=>'images'
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(217793025397592380)
,p_plug_display_sequence=>75
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_result         clob;',
'    l_img            APEX_T_VARCHAR2;',
'    l_single_elemant APEX_T_VARCHAR2;',
'    items            VARCHAR2(5000);',
'    total            integer;',
'BEGIN',
'    l_result := l_result ||''<div class="container-slider">',
'                               <div class="slides">'';',
'',
'    SELECT IMAGES_URL',
'      into items',
'      FROM inspection_details ',
'     WHERE inspection_id = :P16_INSPECTION_ID',
'       AND ITEM_NAME = :P16_TYPE',
'       AND IMAGES_URL IS NOT NULL;',
'',
'    -- IF items IS NULL THEN',
'    --     items := :P2_MAIN_IMAGE_URL;',
'    -- ELSE',
'    --     items := :P2_MAIN_IMAGE_URL || '','' || items;',
'    -- END IF;',
'    l_single_elemant := apex_string.SPLIT (',
'                        p_str => items,',
'                        p_sep => '','' );',
'    ',
'     FOR i in 1 ..l_single_elemant.COUNT LOOP',
'',
'        l_result := l_result || ''<img src="''|| l_single_elemant(i) ||''" alt="">'';',
'    END LOOP;                     ',
'    l_result := l_result ||   ''</div>',
'                               <span class="btn-slide prev">',
'                                   <img src="https://imgur.com/SUyRJqI.png" alt="prevBtn" />',
'                               </span>',
'                               <span class="btn-slide next">',
'                                   <img src=" https://imgur.com/M6rDsRR.png" alt="nextBtn" />',
'                               </span>',
'                               <div class="container-dots">',
'',
'                               </div>',
'                            </div>'';',
'',
'    RETURN l_result;',
'END;'))
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_ajax_items_to_submit=>'P16_INSPECTION_ID'
,p_plug_display_condition_type=>'FUNCTION_BODY'
,p_plug_display_when_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
