wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(65602473635246203)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'car images collections'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE ',
'',
'BEGIN ',
'',
'    FOR i IN ( SELECT c001 AS FILE_NAME, c002 AS MIME_TYPE, blob001 AS BLOB_CONTENT FROM apex_collections WHERE collection_name = ''DROPZONE_UPLOAD'' ) LOOP',
'        IF :P16_TYPE IN (''IS_CAR_WORKING'', ''IS_CAR_HAVE_KEY'', ''ENGINE_NOISE'', ''VALVE_LIFTERS_NOISE'', ''ENGINE_SMOKE'',',
'                         ''ENGINE_DETACHED'', ''TRANSMISSION_TYPE'', ''AIRBAGS'', ''VEHICLE_GLASS'', ''FRONT_CHASSIS'', ''REAR_CHASSIS'',',
'                         ''FRONT_BUMPER_SUPPORT'', ''REAR_BUMPER_SUPPORT'', ''RADIATOR_MOUNT'', ''RIGHT_FRONT_FENDER'', ',
'                         ''LEFT_FRONT_FENDER'', ''RIGHT_REAR_FENDER'', ''LEFT_REAR_FENDER'', ''RIGHT_FRONT_DOOR'',''LEFT_FRONT_DOOR'', ',
'                         ''RIGHT_REAR_DOOR'', ''LEFT_REAR_DOOR'', ''THE_HOOD'', ''THE_ROOF'', ''THE_TRUNK'', ''HAIL_DAMAGE'', ',
'                         ''PAINT_THICKNESS'', ''SCRATCHES'', ''FOUR_WHEEL_DRIVE'', ''SEAT_MATERIAL'')',
'         THEN',
'            IF NOT APEX_COLLECTION.collection_exists(''INSPECTION_IMAGES'') THEN',
'                   APEX_COLLECTION.create_collection(''INSPECTION_IMAGES'');',
'                   APEX_COLLECTION.add_member (',
'                       p_collection_name => ''INSPECTION_IMAGES'',',
'                       p_c001 => i.FILE_NAME, ',
'                       p_c002 => i.MIME_TYPE,',
'                       p_c003 => :P16_TYPE,',
'                       p_c004 => :P16_CAR_DETAILS_ID,',
'                       p_blob001 => i.BLOB_CONTENT',
'                   );',
'               ELSE',
'                   APEX_COLLECTION.add_member (',
'                       p_collection_name => ''INSPECTION_IMAGES'',',
'                       p_c001 => i.FILE_NAME, ',
'                       p_c002 => i.MIME_TYPE,',
'                       p_c003 => :P16_TYPE,',
'                       p_c004 => :P16_CAR_DETAILS_ID,',
'                       p_blob001 => i.BLOB_CONTENT',
'                   );',
'            END IF;',
'        END IF;',
'    END LOOP;',
'    APEX_COLLECTION.TRUNCATE_COLLECTION (p_collection_name => ''DROPZONE_UPLOAD'');',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>31760023102255017
);
