wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(56653000366690856)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Upload Photos'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_file_names        APEX_T_VARCHAR2;',
'    l_file              APEX_APPLICATION_TEMP_FILES%ROWTYPE;',
'    l_file_name         VARCHAR2(255);',
'    l_request_url	    VARCHAR2(32767);',
'    l_result	        CLOB;',
'    l_request_filename	VARCHAR2(500);',
'    l_inner_folder  	VARCHAR2(500);',
'    v_item_name         VARCHAR2(255);',
'    ',
'    type itemsarray IS VARRAY(8) OF VARCHAR2(500); ',
'    items itemsarray;',
'    total integer;',
'BEGIN',
'    items   := itemsarray(:P19_FRONT_RIGHT_CORNER, :P19_FRONT_LEFT_CORNER, :P19_BACK_RIGHT_CORNER, :P19_BACK_LEFT_CORNER, :P19_FRONT_SEATS, :P19_BACK_SEATS, :P19_ODO_METER,:P19_PICKUP_IMAGE_ON_TRUCK);',
'    total   := items.count;',
'',
'    -- Create a collection to store the images',
'    IF NOT APEX_COLLECTION.collection_exists(''TRACKING_IMAGES'') THEN',
'        APEX_COLLECTION.create_collection(''TRACKING_IMAGES'');',
'        APEX_COLLECTION.add_member (',
'            p_collection_name => ''TRACKING_IMAGES'',',
'            p_c009 => ''false''',
'        );',
'    END IF;',
'',
'    FOR i in 1 .. total LOOP',
'        l_file_names := apex_string.SPLIT (',
'                            p_str => items(i),',
'                            p_sep => '':'' );',
'',
'        IF l_file_names.count > 0 THEN',
'            BEGIN',
'                SELECT *',
'                  INTO l_file',
'                  FROM APEX_APPLICATION_TEMP_FILES',
'                 WHERE NAME = items(i)',
'                   AND APPLICATION_ID = :APP_ID;',
'            EXCEPTION',
'                WHEN NO_DATA_FOUND THEN',
'                RAISE_APPLICATION_ERROR(-20003, ''NO DATA FOUND -> '' || items(i));',
'            END;',
'',
'            l_file_name := TO_CHAR(get_current_date, ''YY'') ',
'                        || DBMS_RANDOM.STRING(''x'', 8)',
'                        || SYSTEM_CONTROLS.file_extension_by_mimetype(p_mimetype => l_file.MIME_TYPE);',
'           ',
'            l_request_url := :LOCATION_URI || l_file_name;',
'',
'            BEGIN',
'                DBMS_CLOUD.put_object (',
'                    credential_name => :CREDENTIAL_NAME,',
'                    object_uri      => l_request_url,',
'                    contents        => l_file.blob_content',
'                );',
'            EXCEPTION',
'                WHEN others THEN',
'                    SYSTEM_CONTROLS.ERROR_LOGS(',
'                        p_error_type    => ''SYSTEM_ERROR'',',
'                        p_process_name  => ''DBMS_CLOUD.put_object - App: '' || :APP_ID,',
'                        p_error_code    => -2,',
'                        p_error_message => ''URL: '' || l_request_url || '' - Filename: '' || l_file_name,',
'                        p_logger_name   => :APP_USER',
'                    );',
'            END;',
'',
'            -- Update the collection members with links',
'            APEX_COLLECTION.UPDATE_MEMBER_ATTRIBUTE (',
'                p_collection_name => ''TRACKING_IMAGES'',',
'                p_seq => ''1'',',
'                p_attr_number => i,',
'                p_attr_value => l_request_url',
'            );',
'        END IF;        ',
'    END LOOP;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(56649657058690849)
,p_process_when_type=>'NEVER'
,p_internal_uid=>56653000366690856
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(56652278883690855)
,p_process_sequence=>60
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update transportation offer'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'v_images varchar2(4000);',
'begin',
'IF NOT APEX_COLLECTION.collection_exists(''TRACKING_IMAGES'') THEN',
unistr('        RAISE_APPLICATION_ERROR(-20001, ''\064A\062C\0628 \0639\0644\064A\0643 \0631\0641\0639 \062C\0645\064A\0639 \0635\0648\0631 \0627\0644\0645\0646\062A\062C \0627\0644\0645\0637\0644\0648\0628\0629'');'),
'    ELSIF APEX_COLLECTION.collection_exists(''TRACKING_IMAGES'') THEN',
'        -- Validate the images (if the user not upload all images)',
'        FOR i IN (',
'            SELECT c001, c002, c003, c004, c005, c006, c007',
'              FROM apex_collections',
'             WHERE collection_name = ''TRACKING_IMAGES''',
'               AND seq_id = 1',
'        ) LOOP',
'            IF (i.c001 IS NULL OR i.c002 IS NULL OR i.c003 IS NULL OR i.c004 IS NULL OR',
'               i.c005 IS NULL OR i.c006 IS NULL OR i.c007 IS NULL)',
'            THEN',
unistr('                RAISE_APPLICATION_ERROR(-20001, ''\064A\062C\0628 \0639\0644\064A\0643 \0631\0641\0639 \062C\0645\064A\0639 \0635\0648\0631 \0627\0644\0645\0646\062A\062C \0627\0644\0645\0637\0644\0648\0628\0629'');'),
'            END IF;',
'',
'            v_images     := i.c001|| '',''  ||i.c002 || '', '' || i.c003 || '', '' || i.c004 || '', '' || i.c005 || '', '' || i.c006 || '', '' || i.c007;',
'        END LOOP;',
'    END IF;',
'',
'    update transportation_request_offers set pickup_images_urls = v_images where id = :P19_ID;',
'    UPDATE TRANSPORTATION_REQUESTS',
'       SET IS_AGENT_PICKUP_CONFIRM = 1,',
'           STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''on_the_way'', p_lookup_code => ''transportation_status'')',
'     WHERE ID = :P19_REQUEST_ID;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(56649657058690849)
,p_process_when_type=>'NEVER'
,p_internal_uid=>56652278883690855
);
