,p_plug_name=>'Evaluation Requests'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(217785771929592374)
,p_plug_display_sequence=>25
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT e.ID,',
'       e.EVALUATOR_USER_ID,',
'       e.REQUEST_ID,',
'       e.SELLER_ID as seller_name,',
'       e.BUYER_NAME as owner_name,',
'       e.BUYER_PHONE as owner_phone,',
'       e.CITY,',
'       e.PROPERTY_TYPE,',
'       e.SUB_CATEGORY,',
'       e.INSTRUMENT_NUMBER,',
'       e.SPACE,',
'       e.PROPERTY_PRICE,',
'       e.NOTES,',
'       e.MAP_URL,',
'       e.CONSTRUCTION_LICENSE_URL,',
'       e.INSTRUMENT_URL,',
'       e.CADASTRAL_URL,',
'       e.EVALUATION_URL,',
'    --    NULL AS UPLOAD_FILE,',
'        CASE',
'            WHEN e.EVALUATION_URL IS NULL AND LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => i.AFTER_ASSIGN_STATUS) = ''assigned_evaluator'' THEN',
'                ''<button id="uploadEvaluationg" data-id="'' || e.ID || ''" type="button" class="t-Button t-Button--icon t-Button--hot t-Button--success t-Button--iconRight">',
'                        <span aria-hidden="true" class="fa fa-cloud-arrow-up refresh"></span>',
'                </button>''',
'            WHEN e.EVALUATION_URL IS NOT NULL AND LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => i.AFTER_ASSIGN_STATUS) = ''assigned_evaluator'' THEN',
'                ''<button id="uploadEvaluationg" data-id="'' || e.ID || ''" type="button" class="t-Button t-Button--icon t-Button--iconRight">',
'                        <span aria-hidden="true" class="fa fa-cloud-arrow-up refresh"></span>',
'                </button>''',
'            ELSE ''''',
'        END AS UPLOAD_FILE,',
'       CASE',
'        WHEN e.MAP_URL IS NOT NULL THEN',
'            ''<span class="fa fa-map-marker-o" aria-hidden="true"></span>''',
'        ELSE ''''',
'        END AS MAP_URL_CLASS,',
'',
'       CASE',
'        WHEN e.CONSTRUCTION_LICENSE_URL IS NOT NULL THEN',
'            ''<span class="fa fa-file-arrow-down" aria-hidden="true"></span>''',
'        ELSE ''''',
'        END AS CONSTRUCTION_LICENSE_URL_CLASS,',
'       CASE',
'        WHEN e.INSTRUMENT_URL IS NOT NULL THEN',
'            ''<span class="fa fa-file-arrow-down" aria-hidden="true"></span>''',
'        ELSE ''''',
'        END AS INSTRUMENT_URL_CLASS,',
'       CASE',
'        WHEN e.CADASTRAL_URL IS NOT NULL THEN',
'            ''<span class="fa fa-file-arrow-down" aria-hidden="true"></span>''',
'        ELSE ''''',
'        END AS CADASTRAL_URL_CLASS,',
'       CASE',
'        WHEN e.EVALUATION_URL IS NOT NULL THEN',
'            ''<span class="fa fa-file-arrow-down" aria-hidden="true"></span>''',
'        ELSE ''''',
'        END AS EVALUATION_URL_CLASS,',
'       e.IS_EVALUATED,',
'       CASE ',
'        WHEN e.IS_EVALUATED = 1 THEN ',
'            ''check_row''',
'       END AS CHECK_STYLE,',
'       e.IS_ACTIVE,',
'       e.CREATED_BY,',
'       TO_CHAR(e.CREATED_DATE + 3/24, ''MM/DD/YYYY HH24:MI:SS'') AS CREATED_DATE,',
'       e.MODIFIED_BY,',
'       TO_CHAR(e.MODIFIED_DATE + 3/24, ''MM/DD/YYYY HH24:MI:SS'') AS MODIFIED_DATE',
'  FROM INDIVIDUAL_REALESTATE_EVALUATED_REQUESTS e,',
'       INDIVIDUAL_REALESTATE_REQUESTS i',
' WHERE e.REQUEST_ID = i.ID',
'   AND (e.EVALUATOR_USER_ID = :P_USER_ID OR :P_USER_ID IN (10000, 10002, 9915, 9897))',
' ORDER BY e.ID desc;'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
