,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Agents details'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT a.ID, a.NAME_AR, a.EMAIL, a.PHONE, a.WHATS, a.IS_ACTIVE, a.CREATED_BY, a.CREATED_DATE, a.MODIFIED_BY, a.MODIFIED_DATE, a.IDENTITY_NUMBER, ',
'       a.AGENT_TYPE, a.IDENTITY_URL, t.INSURANCE_TYPE, t.TRUCK_TYPE, t.OPERATION_NO, t.OPERATION_CARD, t.REGISTRATION_URL',
'',
'       INTO :P263_ID, :P263_NAME_AR, :P263_EMAIL, :P263_PHONE, :P263_WHATS, :P263_IS_ACTIVE, :P263_CREATED_BY, :P263_CREATED_DATE, :P263_MODIFIED_BY, :P263_MODIFIED_DATE, :P263_IDENTITY_NUMBER,',
'            :P263_AGENT_TYPE, :P263_IDENTITY_URL, :P263_INSURANCE_TYPE, :P263_TRUCK_TYPE, :P263_OPERATION_NO, :P263_OPERATION_CARD, :P263_REGISTRATION_URL',
'  FROM AGENTS a,',
'       TRANSPORTATION_AGENT_DETAILS t',
' WHERE a.ID = :P263_AGENT_ID',
'       AND a.ID = t.AGENT_ID (+);',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN     ',
'         :P263_ID               := NULL;',
'         :P263_NAME_AR          := NULL;',
'         :P263_EMAIL            := NULL;',
'         :P263_PHONE            := NULL;',
'         :P263_WHATS            := NULL;',
'         :P263_IS_ACTIVE        := NULL;',
'         :P263_CREATED_BY       := NULL;',
'         :P263_CREATED_DATE     := NULL;',
'         :P263_MODIFIED_BY      := NULL;',
'         :P263_MODIFIED_DATE    := NULL;',
'         :P263_IDENTITY_NUMBER  := NULL;',
'         :P263_AGENT_TYPE       := NULL;',
'         :P263_IDENTITY_URL     := NULL;',
'         :P263_INSURANCE_TYPE   := NULL;',
'         :P263_TRUCK_TYPE       := NULL;',
'         :P263_OPERATION_NO     := NULL;',
'         :P263_OPERATION_CARD   := NULL;',
'         :P263_REGISTRATION_URL := NULL;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>70080723819541871
);
