'SELECT m.ID,',
'       m.SELLER_ID,',
'       m.USER_ID,',
'       m.CITY_ID,',
'       m.SEQUENCE,',
'       m.NAME,',
'       m.STATUS_ID,',
'       NVL((SELECT f.FILE_URL FROM SELLER_ASSIGNED_FILES f WHERE f.ID = m.FILE_ID ), ''#'') AS FILE_URL,',
'       m.IS_ACTIVE,',
'       m.CREATED_BY,',
'       m.CREATED_DATE,',
'       m.MODIFIED_BY,',
'       m.MODIFIED_DATE,',
'       m.FILE_ID,',
'       (SELECT count(1) FROM seller_assigned_files_details WHERE master_id = m.id AND is_active = 1 ) AS VEHICLES_COUNT,',
'       ''<span aria-hidden="true" class="t-Icon fa fa-cloud-upload"></span>'' AS UPLOAD,',
'       ',
'       ''<span aria-hidden="true" class="t-Icon fa fa-cloud-upload"></span>'' AS UPLOAD_PAYMENT_DOCUMENT,',
'       m.AGENT_PHOTOGRAPHY_PAYMENT_DOCUMENT,',
'       CASE',
'      WHEN m.AGENT_PHOTOGRAPHY_PAYMENT_DOCUMENT IS NOT NULL THEN',
'          ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'      ELSE ''''',
'      END AS AGENT_PHOTOGRAPHY_PAYMENT_DOCUMENT_CLASS,',
'       m.PHOTOGRAPHY_PAYMENT_DOCUMENT,',
'       CASE',
'      WHEN m.PHOTOGRAPHY_PAYMENT_DOCUMENT IS NOT NULL THEN',
'          ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'      ELSE ''''',
'      END AS PHOTOGRAPHY_PAYMENT_DOCUMENT_CLASS',
'  FROM SELLER_ASSIGNED_FILES_MASTER m',
' WHERE (USER_ID = :P_USER_ID OR :P_USER_ID IN (10000, 10002, 9915, 9897, 10610,10621))',
'   AND IS_ACTIVE = 1',
' ORDER BY sequence DESC;'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_page_header=>'Assigned Files Container'
);
