,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('SELECT ''<img class="carImage" alt="\0644\0627 \062A\0648\062C\062F \0635\0648\0631\0629" src='' || c001 || '' />'' AS FRONT_RIGHT_CORNER,'),
