wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(96250898049425850)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Upload Photos'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_file_names        APEX_T_VARCHAR2;',
'    l_file              APEX_APPLICATION_TEMP_FILES%ROWTYPE;',
'    l_file_name         VARCHAR2(255);',
'    l_request_url	    VARCHAR2(32767);',
'    l_result	        CLOB;',
'    l_request_filename	VARCHAR2(500);',
'    l_inner_folder  	VARCHAR2(500);',
'    v_item_name         VARCHAR2(255);',
'    ',
'    type itemsarray IS VARRAY(7) OF VARCHAR2(500); ',
'    items_names itemsarray; ',
'    items itemsarray; ',
'    total integer; ',
'BEGIN',
'    items_names := itemsarray(''P271_FRONT_RIGHT_CORNER_URL'', ''P271_FRONT_LEFT_CORNER_URL'', ''P271_BACK_RIGHT_CORNER_URL'', ''P271_BACK_LEFT_CORNER_URL'', ''P271_FRONT_SEATS_URL'', ''P271_BACK_SEATS_URL'', ''P271_ODO_METER_URL'');',
'    items := itemsarray(:P271_FRONT_RIGHT_CORNER, :P271_FRONT_LEFT_CORNER, :P271_BACK_RIGHT_CORNER, :P271_BACK_LEFT_CORNER, :P271_FRONT_SEATS, :P271_BACK_SEATS, :P271_ODO_METER);',
'    total := items.count; ',
'',
'    FOR i in 1 .. total LOOP',
'        l_file_names := apex_string.SPLIT (',
'                            p_str => items(i),',
'                            p_sep => '':'' );',
'',
'        -- IF :P271_IS_PHOTO_TAKEN = 1 AND l_file_names.count = 0 THEN',
unistr('        --     RAISE_APPLICATION_ERROR(-20001, ''\064A\062C\0628 \0639\0644\064A\0643 \0631\0641\0639 \062C\0645\064A\0639 \0627\0644\0635\0648\0631 \0623\0648\0644\0627'');'),
'        -- END IF;',
'',
'        -- IF :P271_IS_PHOTO_TAKEN = 0 AND l_file_names.count > 0 THEN',
unistr('        --     RAISE_APPLICATION_ERROR(-20002, ''\064A\062C\0628 \0639\0644\064A\0643 \062A\0641\0639\064A\0644 \0632\0631 (\062A\0645 \0627\0644\062A\0635\0648\064A\0631) \0623\0648\0644\0627'');'),
'        -- END IF;',
'',
'        IF l_file_names.count > 0 THEN',
'            BEGIN',
'                SELECT *',
'                  INTO l_file',
'                  FROM APEX_APPLICATION_TEMP_FILES',
'                 WHERE NAME = items(i)',
'                   AND APPLICATION_ID = :APP_ID;',
'            EXCEPTION',
'                WHEN NO_DATA_FOUND THEN',
'                RAISE_APPLICATION_ERROR(-20003, ''NO DATA FOUND -> '' || items(i));',
'            END;',
'',
'            -- l_file_name := :P271_CHASSIS_NUMBER || ''-'' || i || SYSTEM_CONTROLS.file_extension_by_mimetype(p_mimetype => l_file.MIME_TYPE);',
'',
'            l_file_name := TO_CHAR(get_current_date, ''YY'') ',
'                        || DBMS_RANDOM.STRING(''x'', 8)',
'                        || SYSTEM_CONTROLS.file_extension_by_mimetype(p_mimetype => l_file.MIME_TYPE);',
'           ',
'            l_request_url := :LOCATION_URI || l_file_name;',
'',
'            DBMS_CLOUD.put_object (',
'                credential_name => :CREDENTIAL_NAME,',
'                object_uri      => l_request_url,',
'                contents        => l_file.blob_content',
'            );',
'',
'            SELECT item_name',
'              INTO v_item_name',
'              FROM APEX_APPLICATION_PAGE_ITEMS',
'             WHERE APPLICATION_ID = :APP_ID',
'               AND PAGE_ID = :APP_PAGE_ID',
'               AND item_name = items_names(i);',
'            --    AND item_name LIKE ''%'' || items_names(i) || ''_URL%'';',
'',
'            APEX_UTIL.SET_SESSION_STATE (v_item_name, l_request_url);',
'        END IF;',
'    END LOOP;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(96217613574425884)
,p_internal_uid=>8424828258105658
);
