 p_id=>wwv_flow_imp.id(96250482571425851)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update the status'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    UPDATE SELLER_ASSIGNED_FILES_DETAILS',
'       SET STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''done'', p_lookup_code => ''assigned_files_status''),',
'           IS_UPLOADED = 1,',
'           FRONT_RIGHT_CORNER = :P271_FRONT_RIGHT_CORNER_URL,',
'           FRONT_LEFT_CORNER  = :P271_FRONT_LEFT_CORNER_URL,',
'           BACK_RIGHT_CORNER  = :P271_BACK_RIGHT_CORNER_URL,',
'           BACK_LEFT_CORNER   = :P271_BACK_LEFT_CORNER_URL,',
'           FRONT_SEATS        = :P271_FRONT_SEATS_URL,',
'           BACK_SEATS         = :P271_BACK_SEATS_URL,',
'           ODO_METER          = :P271_ODO_METER_URL',
'     WHERE ID = :P271_ID;',
'',
'    IF SQL%ROWCOUNT = 0 THEN',
'          RAISE_APPLICATION_ERROR(-20001, ''Updating Error'');',
'    END IF;',
'',
'    -- APEX_UTIL.SET_SESSION_STATE (''P271_FRONT_RIGHT_CORNER_URL'', :P271_FRONT_RIGHT_CORNER_URL);',
'/*',
'    IF :P271_IS_WASHED = 1 AND :P271_IS_STICKERED = 1 AND :P271_IS_PHOTO_TAKEN = 1 THEN',
'        UPDATE SELLER_ASSIGNED_FILES_DETAILS',
'           SET STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''done'', p_lookup_code => ''assigned_files_status'')',
'         WHERE ID = :P271_ID;',
'',
'        -- UPDATE MASTER STATUS',
'        UPDATE SELLER_ASSIGNED_FILES_MASTER',
'           SET STATUS_ID = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''under_process'', p_lookup_code => ''seller_assigned_files_status'')',
'         WHERE ID = :P271_MASTER_ID;',
'    ELSIF :P271_IS_WASHED = 1 AND :P271_IS_STICKERED = 0 AND :P271_IS_PHOTO_TAKEN = 0 THEN',
'        UPDATE SELLER_ASSIGNED_FILES_DETAILS',
'           SET STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''waiting_sticker'', p_lookup_code => ''assigned_files_status'')',
'         WHERE ID = :P271_ID;',
'    ELSIF :P271_IS_WASHED = 0 AND :P271_IS_STICKERED = 0 AND :P271_IS_PHOTO_TAKEN = 0 THEN',
'        UPDATE SELLER_ASSIGNED_FILES_DETAILS',
'           SET STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''waiting_washing'', p_lookup_code => ''assigned_files_status'')',
'         WHERE ID = :P271_ID;',
'    ELSIF :P271_IS_WASHED = 1 AND :P271_IS_STICKERED = 1 AND :P271_IS_PHOTO_TAKEN = 0 THEN',
'        UPDATE SELLER_ASSIGNED_FILES_DETAILS',
'           SET STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''waiting_photography'', p_lookup_code => ''assigned_files_status'')',
'         WHERE ID = :P271_ID;',
'    END IF;',
'*/',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(96217613574425884)
,p_internal_uid=>8424412780105659
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(96251760347425849)
,p_process_sequence=>50
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Send Images API'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_body      CLOB;',
'    l_result    CLOB;',
'    l_message   CLOB;',
'    header      json_object_t;',
'    images      json_array_t;',
'BEGIN',
'    header  := json_object_t();',
'    images  := json_array_t();',
'',
'    -- RAISE_APPLICATION_ERROR (-20007, ''1- '' || :P271_FRONT_RIGHT_CORNER_URL || '' 2- '' || :P271_SELLER_ID);',
'',
'    images.append(:P271_FRONT_RIGHT_CORNER_URL);',
'    images.append(:P271_FRONT_LEFT_CORNER_URL);',
'',
'    IF :P271_BACK_RIGHT_CORNER_URL IS NOT NULL THEN',
'        images.append(:P271_BACK_RIGHT_CORNER_URL);',
'    END IF;',
'    IF :P271_BACK_LEFT_CORNER_URL IS NOT NULL THEN',
'        images.append(:P271_BACK_LEFT_CORNER_URL);',
'    END IF;',
'    IF :P271_FRONT_SEATS_URL IS NOT NULL THEN',
'        images.append(:P271_FRONT_SEATS_URL);',
'    END IF;',
'    IF :P271_BACK_SEATS_URL IS NOT NULL THEN',
'        images.append(:P271_BACK_SEATS_URL);',
'    END IF;',
'    IF :P271_ODO_METER_URL IS NOT NULL THEN',
'        images.append(:P271_ODO_METER_URL);',
'    END IF;',
'',
'    header.put(''mainImageUrl'', :P271_FRONT_RIGHT_CORNER_URL);',
'    header.put(''imagesUrls'', images);',
'    header.put(''uploadedBy'', :P_USER_ID);',
'',
'    -- RAISE_APPLICATION_ERROR (-20009, header.to_clob());',
'    -- RAISE_APPLICATION_ERROR (-20009, ''https://backend-master.mobasher.sa/products/'' || :P271_SELLER_ID || ''/'' || :P271_RES_PRODUCT_ID);',
'',
'    l_result := SYSTEM_INTEGRATION.send_vehicle_images (',
'                    p_body          => header.to_clob(),',
'                    p_seller_id     => :P271_SELLER_ID,',
'                    p_product_id    => :P271_RES_PRODUCT_ID,',
'                    p_message       => l_message',
'                );',
'',
'    IF l_result <> ''1'' THEN',
'        RAISE_APPLICATION_ERROR (-20007, l_message);',
'    END IF;',
'',
'    header  := json_object_t();',
'    images  := json_array_t();',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(96217613574425884)
,p_process_success_message=>unistr('\062A\0645 \0631\0641\0639 \0627\0644\0635\0648\0631 \0628\0646\062C\0627\062D')
,p_internal_uid=>8425690556105657
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(96249699959425852)
,p_process_sequence=>80
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'update images'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN ',
'    SELECT c001, c002, c003, c004, c005, c006, c007 ',
'      INTO :P271_UPDATE_FRONT_RIGHT_CORNER_URL, :P271_UPDATE_FRONT_LEFT_CORNER_URL, :P271_UPDATE_BACK_RIGHT_CORNER_URL, :P271_UPDATE_BACK_LEFT_CORNER_URL, :P271_UPDATE_FRONT_SEATS_URL, :P271_UPDATE_BACK_SEATS_URL, :P271_UPDATE_ODO_METER_URL',
'    FROM APEX_COLLECTIONS ',
'   WHERE COLLECTION_NAME = ''VEHICLE_IMAGES'';',
'',
'UPDATE SELLER_ASSIGNED_FILES_DETAILS ',
'   SET FRONT_RIGHT_CORNER = :P271_UPDATE_FRONT_RIGHT_CORNER_URL, ',
'       FRONT_LEFT_CORNER  = :P271_UPDATE_FRONT_LEFT_CORNER_URL, ',
'       BACK_RIGHT_CORNER  = :P271_UPDATE_BACK_RIGHT_CORNER_URL, ',
'       BACK_LEFT_CORNER   = :P271_UPDATE_BACK_LEFT_CORNER_URL, ',
'       FRONT_SEATS        = :P271_UPDATE_FRONT_SEATS_URL, ',
'       BACK_SEATS         = :P271_UPDATE_BACK_SEATS_URL, ',
'       ODO_METER          = :P271_UPDATE_ODO_METER_URL',
' WHERE ID = :P271_ID; ',
'',
' IF SQL%ROWCOUNT = 0 THEN',
'     RAISE_APPLICATION_ERROR(-20003, ''Updating Error'');',
' END IF;',
'',
'APEX_COLLECTION.TRUNCATE_COLLECTION (p_collection_name => ''VEHICLE_IMAGES'');',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(96242828794425858)
,p_internal_uid=>8423630168105660
);
