wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(96251273558425850)
,p_process_sequence=>110
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Check if all done'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_result   NUMBER;',
'    v_products NUMBER;',
'    v_message  VARCHAR2(500);',
'BEGIN',
'    v_result := SELLER.change_status_to_done ( p_master_id => :P271_MASTER_ID );',
'',
'    IF v_result = 1 THEN',
'        v_products :=  SELLER.create_products (',
'                            p_seller_id       => :P271_SELLER_ID,',
'                            p_city_id         => :P271_CITY_ID,',
'                            p_category_id     => 2,',
'                            p_subcategory_id  => 1,',
'                            p_type            => ''SELLER_PRODUCT'',',
'                            p_warranty        => ''AS_IS'',',
'                            p_name_ar         => :P271_TYPE ||'' ''|| :P271_MODEL ||'' ''|| :P271_MODEL_YEAR,',
'                            p_name_en         => :P271_TYPE ||'' ''|| :P271_MODEL ||'' ''|| :P271_MODEL_YEAR,',
unistr('                            p_desc_ar         => :P271_TYPE ||'' ''|| :P271_MODEL ||'' ''|| :P271_MODEL_YEAR ||'' \0644\0648\0646 ''|| :P271_COLOR ||'' \0631\0642\0645 \0644\0648\062D\0629 ''|| :P271_PLATE_NUMBER ||'' \0645\0642\064A\0627\0633 \0627\0644\0633\0631\0639\0629 ''|| :P271_SPEED_OMETER ||'' \0643\0645'','),
unistr('                            p_desc_en         => :P271_TYPE ||'' ''|| :P271_MODEL ||'' ''|| :P271_MODEL_YEAR ||'' \0644\0648\0646 ''|| :P271_COLOR ||'' \0631\0642\0645 \0644\0648\062D\0629 ''|| :P271_PLATE_NUMBER ||'' \0645\0642\064A\0627\0633 \0627\0644\0633\0631\0639\0629 ''|| :P271_SPEED_OMETER ||'' \0643\0645'','),
'                            p_notes           => :P271_NOTES,',
'                            p_main_image_url  => :P271_FRONT_RIGHT_CORNER,',
'                            p_images_urls     => :P271_FRONT_RIGHT_CORNER||'', ''||:P271_FRONT_LEFT_CORNER||'', ''||:P271_BACK_RIGHT_CORNER||'', ''||:P271_BACK_LEFT_CORNER||'', ''||:P271_FRONT_SEATS||'', ''||:P271_BACK_SEATS||'', ''||:P271_ODO_METER,',
'                            p_make            => :P271_TYPE,',
'                            p_model           => :P271_MODEL,',
'                            p_year            => :P271_MODEL_YEAR,',
'                            p_color           => :P271_COLOR,',
'                            p_fuel_type       => :P271_FUEL_TYPE,',
'                            p_card_notes      => :P271_NOTES,',
'                            p_odo_meter       => :P271_SPEED_OMETER,',
'                            p_is_document     => 0,',
'                            p_is_inspection   => 0,',
'                            p_lang            => :P_LANG,',
'                            p_message         => v_message',
'                        );',
'        IF v_products <> 1 THEN',
'            RAISE_APPLICATION_ERROR (-20001, ''Create Products Error: '' || v_message);',
'        END IF;',
'    ELSE',
