 p_id=>wwv_flow_imp.id(96249348464425852)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'get data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE ',
'    v_front_right_corner VARCHAR2(2000);',
'    v_front_left_corner VARCHAR2(2000);',
'    v_back_right_corner VARCHAR2(2000);',
'    v_back_left_corner VARCHAR2(2000);',
'    v_front_seats      VARCHAR2(2000);',
'    v_back_seats       VARCHAR2(2000);',
'    v_odo_meter        VARCHAR2(2000);',
'BEGIN',
'    IF :P271_IS_UPLOADED = 1 THEN ',
'        SELECT FRONT_RIGHT_CORNER, FRONT_LEFT_CORNER, BACK_RIGHT_CORNER, BACK_LEFT_CORNER, FRONT_SEATS, BACK_SEATS, ODO_METER',
'          INTO v_front_right_corner, v_front_left_corner, v_back_right_corner, v_back_left_corner, v_front_seats, v_back_seats, v_odo_meter',
'          FROM SELLER_ASSIGNED_FILES_DETAILS',
'         WHERE ID = :P271_ID;',
'',
'        IF NOT APEX_COLLECTION.collection_exists(''VEHICLE_IMAGES'') THEN',
'            APEX_COLLECTION.create_collection(''VEHICLE_IMAGES'');',
'            APEX_COLLECTION.add_member (',
'                p_collection_name => ''VEHICLE_IMAGES'',',
'                p_c001 => v_front_right_corner, ',
'                p_c002 => v_front_left_corner,',
'                p_c003 => v_back_right_corner,',
'                p_c004 => v_back_left_corner,',
'                p_c005 => v_front_seats,',
'                p_c006 => v_back_seats,',
'                p_c007 => v_odo_meter',
'            );',
'        ELSE',
'            APEX_COLLECTION.TRUNCATE_COLLECTION (p_collection_name => ''VEHICLE_IMAGES'');',
'            APEX_COLLECTION.add_member (',
'                p_collection_name => ''VEHICLE_IMAGES'',',
'                p_c001 => v_front_right_corner, ',
'                p_c002 => v_front_left_corner,',
'                p_c003 => v_back_right_corner,',
'                p_c004 => v_back_left_corner,',
'                p_c005 => v_front_seats,',
'                p_c006 => v_back_seats,',
'                p_c007 => v_odo_meter',
'            );',
'        END IF;',
'    -- ELSE',
'    --     APEX_COLLECTION.TRUNCATE_COLLECTION (p_collection_name => ''VEHICLE_IMAGES'');',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>8423278673105660
);
end;
