'DECLARE ',
'    l_request_url	    VARCHAR2(5000);',
'    l_bucket_name	    VARCHAR2(32767) := ''seller-assign-car-photos'';',
'BEGIN',
'    IF :P272_COLUMN_NAME_ADD = ''FRONT_RIGHT_CORNER'' THEN',
'        l_request_url := SYSTEM_CONTROLS.upload (p_item => :P272_UPDATE_FRONT_RIGHT_CORNER,',
'                                                 p_bucket_name => l_bucket_name,',
'                                                 p_is_required => 1);',
'        APEX_COLLECTION.UPDATE_MEMBER_ATTRIBUTE (',
'            p_collection_name => ''VEHICLE_IMAGES'',',
'            p_seq => ''1'',',
'            p_attr_number => 1,',
'            p_attr_value => l_request_url);',
'',
'    ELSIF :P272_COLUMN_NAME_ADD = ''FRONT_LEFT_CORNER'' THEN',
'           l_request_url := SYSTEM_CONTROLS.upload (p_item => :P272_UPDATE_FRONT_LEFT_CORNER,',
'                                                    p_bucket_name => l_bucket_name,',
'                                                    p_is_required => 1);',
'           APEX_COLLECTION.UPDATE_MEMBER_ATTRIBUTE (',
'               p_collection_name => ''VEHICLE_IMAGES'',',
'               p_seq => ''1'',',
'               p_attr_number => 2,',
'               p_attr_value => l_request_url);',
'',
'    ELSIF :P272_COLUMN_NAME_ADD = ''BACK_RIGHT_CORNER'' THEN',
'           l_request_url := SYSTEM_CONTROLS.upload (p_item => :P272_UPDATE_BACK_RIGHT_CORNER,',
'                                                    p_bucket_name => l_bucket_name,',
'                                                    p_is_required => 1);',
'        APEX_COLLECTION.UPDATE_MEMBER_ATTRIBUTE (',
'            p_collection_name => ''VEHICLE_IMAGES'',',
'            p_seq => ''1'',',
'            p_attr_number => 3,',
'            p_attr_value => l_request_url);',
'',
'    ELSIF :P272_COLUMN_NAME_ADD = ''BACK_LEFT_CORNER'' THEN',
'           l_request_url := SYSTEM_CONTROLS.upload (p_item => :P272_UPDATE_BACK_LEFT_CORNER,',
'                                                    p_bucket_name => l_bucket_name,',
'                                                    p_is_required => 1);',
'        APEX_COLLECTION.UPDATE_MEMBER_ATTRIBUTE (',
'            p_collection_name => ''VEHICLE_IMAGES'',',
'            p_seq => ''1'',',
'            p_attr_number => 4,',
'            p_attr_value => l_request_url);',
'        ',
'    ELSIF :P272_COLUMN_NAME_ADD = ''FRONT_SEATS'' THEN',
'           l_request_url := SYSTEM_CONTROLS.upload (p_item => :P272_UPDATE_FRONT_SEATS,',
'                                                    p_bucket_name => l_bucket_name,',
'                                                    p_is_required => 1);',
'        APEX_COLLECTION.UPDATE_MEMBER_ATTRIBUTE (',
'            p_collection_name => ''VEHICLE_IMAGES'',',
'            p_seq => ''1'',',
'            p_attr_number => 5,',
'            p_attr_value => l_request_url);',
'        ',
'    ELSIF :P272_COLUMN_NAME_ADD = ''BACK_SEATS'' THEN',
'           l_request_url := SYSTEM_CONTROLS.upload (p_item => :P272_UPDATE_BACK_SEATS,',
'                                                    p_bucket_name => l_bucket_name,',
'                                                    p_is_required => 1);',
'        APEX_COLLECTION.UPDATE_MEMBER_ATTRIBUTE (',
'            p_collection_name => ''VEHICLE_IMAGES'',',
'            p_seq => ''1'',',
'            p_attr_number => 6,',
'            p_attr_value => l_request_url);',
'        ',
'    ELSIF :P272_COLUMN_NAME_ADD = ''ODO_METER'' THEN',
'           l_request_url := SYSTEM_CONTROLS.upload (p_item => :P272_UPDATE_ODO_METER,',
'                                                    p_bucket_name => l_bucket_name,',
'                                                    p_is_required => 1);',
'        APEX_COLLECTION.UPDATE_MEMBER_ATTRIBUTE (',
'            p_collection_name => ''VEHICLE_IMAGES'',',
'            p_seq => ''1'',',
'            p_attr_number => 7,',
'            p_attr_value => l_request_url);    ',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>32252913707982407
