'       PRODUCT_NAME,',
'       VIN_NUMBER,',
'       PLATE_NUMBER,',
'       YEAR,',
'       BUYER_NID_URL,',
'       SELLER_FORM_URL,',
'       SELLER_WAIVER_URL,',
'       SELLER_DELEGATION_URL,',
'       AGENT_DOCUMENT_URL,',
'       ''<img src="''|| IMAGE_URL ||''" alt="Main Image" class="product-image" style="width:25px;height:25px;" />'' AS MAIN_IMAGE,',
'       CASE',
'        WHEN SELLER_FORM_URL IS NOT NULL THEN',
'            ''<span aria-hidden="true" class="fa fa-file-arrow-down"></span>''',
'        ELSE ''''',
'       END AS FORM_URL_CLASS,',
'       CASE',
'        WHEN SELLER_WAIVER_URL IS NOT NULL THEN',
'            ''<span aria-hidden="true" class="fa fa-file-arrow-down"></span>''',
'        ELSE ''''',
'       END AS WAIVER_URL_CLASS,',
'       CASE',
'        WHEN SELLER_DELEGATION_URL IS NOT NULL THEN',
'            ''<span aria-hidden="true" class="fa fa-file-arrow-down"></span>''',
'        ELSE ''''',
'       END AS DELEGATION_URL_CLASS,',
'       CASE',
'        WHEN BUYER_NID_URL IS NOT NULL THEN',
'            ''<span aria-hidden="true" class="fa fa-file-arrow-down"></span>''',
'        ELSE ''''',
'       END AS BUYER_NID_URL_CLASS,',
'       CASE',
'        WHEN AGENT_DOCUMENT_URL IS NOT NULL THEN',
'            ''<span aria-hidden="true" class="fa fa-file-arrow-down"></span>''',
'        ELSE ''''',
'       END AS AGENT_DOCUMENT_URL_CLASS,',
'       NULL AS UPLOAD_FORM',
'  FROM SERVICES_AGENT_REQUESTS',
'   WHERE NVL(IS_ACTIVE, 0) = 1',
'    --  AND AGENTS_PKG.user_id_by_agent_id (p_agent_id => AGENT_ID) = :P_USER_ID',
' ORDER BY ID;'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_page_header=>'Sold Products'
);
