'    l_body := ''{',
'                 "id": "''|| :P997_REQUEST_ID ||''",',
'                 "transferProof": "''|| l_request_url ||''"',
'            }'';',
'',
'    l_result := SYSTEM_INTEGRATION.send_services_agent_file (',
'                    p_body    => l_body,',
'                    p_message => l_message',
'                );',
'',
'    IF l_result <> ''1'' THEN',
'        RAISE_APPLICATION_ERROR (-20007, l_message);',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
