'DECLARE',
'    l_count    NUMBER;',
'BEGIN',
'    SELECT COUNT(1)',
'      INTO l_count',
'      FROM APP_USERS',
'     WHERE OBJECT_TYPE = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''agent'', p_lookup_code => ''user_type'')',
'       AND TRIM(LOWER(USER_NAME)) = TRIM(LOWER(:P9999_USERNAME))',
'        OR ID IN (10000, 10002);',
'',
'    IF l_count = 0 THEN',
unistr('        RAISE_APPLICATION_ERROR (-20001, ''\064A\062C\0628 \0623\0646 \062A\0643\0648\0646 \0648\0643\064A\0644 \062E\062F\0645\0627\062A \0644\062F\0649 \0645\0646\0635\0629 \0645\0628\0627\0634\0631 \0644\0644\0645\0632\0627\062F\0627\062A'');'),
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>13036022071147026
);
