,p_process_name=>'save token'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_token VARCHAR2(400) := SYS_GUID();',
'  l_url   VARCHAR2(4000);',
'  l_id    PLS_INTEGER;',
'BEGIN',
'  BEGIN',
'    INSERT INTO TEMP_COMPANIES (EMAIL,PHONE,',
'      NAME_AR, CRN, ADDRESS, CITY_ID, NEIGHBORHOOD_ID,',
'      STREET, ZIP_CODE, PO_BOX, TOKEN',
'    ) VALUES (:P10010_EMAIL,:P10010_PHONE,',
'      :P10010_NAME_AR, :P10010_CRN, :P10010_ADDRESS,',
'      :P10010_CITY_ID, :P10010_NEIGHBORHOOD_ID,',
'      :P10010_STREET, :P10010_ZIP_CODE, :P10010_PO_BOX,',
'      l_token',
'    ) returning id into l_id;',
'    APEX_DEBUG.MESSAGE(''Insert successful for token: '' || l_token);',
'  EXCEPTION',
'    WHEN OTHERS THEN',
'      APEX_DEBUG.MESSAGE(''Insert failed: '' || SQLERRM);',
'  END;',
'  -- Redirect regardless',
'  :P10010_TOKEN := l_token;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>36134012100245648
);
