'let otpTimerId = null;',
'',
'function startOtpCountdown(expiresAtStr) {',
'  const countdownEl     = document.getElementById("otp-countdown");',
'  const resendContainer = document.getElementById("otp-resend-container");',
'  if (!countdownEl) return;',
'',
unistr('  // \2460 Hide the resend link & reset countdown color on each start'),
'  if (resendContainer) {',
'    resendContainer.style.display = ''none'';',
'  }',
'  countdownEl.style.color = '''';  // clears any inline color, falling back to CSS',
'',
unistr('  // \2461 Clear any existing timer'),
'  if (otpTimerId) {',
'    clearInterval(otpTimerId);',
'  }',
'',
'  const expiresAt = new Date(expiresAtStr);',
'  function update() {',
'    const diffMs = expiresAt - new Date();',
'    if (diffMs <= 0) {',
unistr('      countdownEl.textContent = "\0627\0646\062A\0647\062A \0635\0644\0627\062D\064A\0629 \0627\0644\0631\0645\0632";'),
'      countdownEl.style.color = "#999";      // expired text color',
'      if (resendContainer) {',
'        resendContainer.style.display = ''block'';',
'      }',
'      clearInterval(otpTimerId);',
'      return;',
'    }',
'    const m = Math.floor(diffMs / 60000);',
'    const s = Math.floor((diffMs % 60000) / 1000)',
'                  .toString()',
'                  .padStart(2, ''0'');',
unistr('    countdownEl.textContent = `\0627\0644\0631\0645\0632 \064A\0646\062A\0647\064A \062E\0644\0627\0644 ${m}:${s}`;'),
'  }',
'',
'  // run immediately, then every second',
'  update();',
'  otpTimerId = setInterval(update, 1000);',
'}',
''))
