'(function() {',
'  const countdownEl = document.getElementById("otp-countdown");',
'  const resendContainer = document.getElementById("otp-resend-container");',
'',
'  if (!countdownEl) {',
unistr('    console.warn("\23F1\FE0F Element #otp-countdown not found on page.");'),
'    return;',
'  }',
'    console.log($v("P10011_OTP_EXPIRES_AT"));',
'',
'  const expiresAtStr = $v("P10011_OTP_EXPIRES_AT");',
'',
'  if (!expiresAtStr) {',
unistr('    countdownEl.textContent = "\0644\0645 \064A\062A\0645 \062A\0639\064A\064A\0646 \0648\0642\062A \0627\0644\0627\0646\062A\0647\0627\0621";'),
'    return;',
'  }',
'',
'  const expiresAt = new Date(expiresAtStr);',
'  let timer;',
'',
'  function updateCountdown() {',
'    const now = new Date();',
'    const diffMs = expiresAt - now;',
'',
'    if (diffMs <= 0) {',
unistr('      countdownEl.textContent = "\0627\0646\062A\0647\062A \0635\0644\0627\062D\064A\0629 \0627\0644\0631\0645\0632";'),
'      countdownEl.style.color = "#999";',
'',
'      if (resendContainer) {',
'        resendContainer.style.display = "block";',
'      }',
'',
'      clearInterval(timer);',
'      return;',
'    }',
'',
'    const minutes = Math.floor(diffMs / 60000);',
'    const seconds = Math.floor((diffMs % 60000) / 1000);',
'',
unistr('    countdownEl.textContent = `\0627\0644\0631\0645\0632 \064A\0646\062A\0647\064A \062E\0644\0627\0644 ${minutes}:${seconds.toString().padStart(2, ''0'')}`;'),
'  }',
'',
'  updateCountdown();',
'  timer = setInterval(updateCountdown, 1000);',
'})();',
''))
);
