wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(36132806483245636)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'get contract'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_text       CLOB;',
'    l_city_name  cities.name_ar%TYPE;',
'    l_hood_name  neighbourhoods.name_ar%TYPE;',
'',
'    -- TEMP_COMPANIES fields',
'    l_id          TEMP_COMPANIES.ID%TYPE;  ',
'    l_name_ar     TEMP_COMPANIES.NAME_AR%TYPE;',
'    l_crn         TEMP_COMPANIES.CRN%TYPE;',
'    l_address     TEMP_COMPANIES.ADDRESS%TYPE;',
'    l_city_id     TEMP_COMPANIES.CITY_ID%TYPE;',
'    l_hood_id     TEMP_COMPANIES.NEIGHBORHOOD_ID%TYPE;',
'    l_street      TEMP_COMPANIES.STREET%TYPE;',
'    l_po_box      TEMP_COMPANIES.PO_BOX%TYPE;',
'    l_zip_code    TEMP_COMPANIES.ZIP_CODE%TYPE;',
'',
'    l_hijri_date VARCHAR2(50) := to_char(sysdate,''DD Month YYYY'',''nls_calendar=''''arabic hijrah'''''');',
'    l_contract_date varchar2(20) := to_char(to_date(sysdate,''DD/MM/YYYY''),''DD/MM/YYYY'');',
'BEGIN',
'    -- Step 1: Fetch company data using token',
'    SELECT ID, NAME_AR, CRN, ADDRESS, CITY_ID, NEIGHBORHOOD_ID, STREET, PO_BOX, ZIP_CODE',
'    INTO   l_id, l_name_ar, l_crn, l_address, l_city_id, l_hood_id, l_street, l_po_box, l_zip_code',
'    FROM   TEMP_COMPANIES',
'    WHERE  TOKEN = :P10011_TOKEN;',
'',
'    -- Step 2: Lookup city name',
'    SELECT NAME_AR INTO l_city_name FROM CITIES WHERE ID = l_city_id;',
'',
'    -- Step 3: Lookup hood name (optional)',
'    BEGIN',
'        SELECT NAME_AR INTO l_hood_name FROM NEIGHBOURHOODS WHERE ID = l_hood_id;',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            l_hood_name := '' - '';',
'    END;',
'',
'    -- Step 4: Load contract template',
'    SELECT CLOB_VALUE',
'    INTO   l_text',
'    FROM   SYSTEM_CONFIGRATIONS',
'    WHERE  KEY = ''AGENT_CONTRACTS_COMPANY'';',
'',
'    -- Step 5: Replace placeholders',
'    l_text := REPLACE(l_text, ''{NAME}'',      l_name_ar);',
'    l_text := REPLACE(l_text, ''{CRN}'',       l_crn);',
'    l_text := REPLACE(l_text, ''{ADDRESS}'',   l_address);',
'    l_text := REPLACE(l_text, ''{CITY}'',      l_city_name);',
'    l_text := REPLACE(l_text, ''{HOOD}'',      l_hood_name);',
'    l_text := REPLACE(l_text, ''{STREET}'',    l_street);',
'    l_text := REPLACE(l_text, ''{PO_BOX}'',    l_po_box);',
'    l_text := REPLACE(l_text, ''{ZIP_CODE}'',  l_zip_code);',
'    l_text := REPLACE(l_text, ''{CONTRACT_DATE_HIJ}'', TO_CLOB(l_hijri_date));',
'    l_text := REPLACE(l_text, ''{CONTRACT_DATE}'', l_contract_date);',
'    -- Step 6: Assign result to page item',
'    :P10011_CONTRACT := l_text;',
'',
'    -- Optional: Assign values to other items if you want to display them too',
'    :P10011_TEMP_COMPANY_ID := l_id; --- temp company id',
'    :P10011_NAME_AR := l_name_ar;',
'    :P10011_CRN := l_crn;',
'    :P10011_ADDRESS := l_address;',
'    :P10011_CITY_ID := l_city_id;',
